package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sync"
	"time"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	conf      float64
}

func (b *liquidityBelief) observePass(amt,
	capacity lnwire.MilliSatoshi) {

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}

	// With bimodal balances, passing even a moderate HTLC is evidence
	// favoring the high-liquidity mode.
	highEstimate := capacity * 9 / 10
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.estimate < highEstimate {
		b.estimate = highEstimate
	}

	b.conf += 2
	if b.conf > 12 {
		b.conf = 12
	}
}

func (b *liquidityBelief) observeFail(amt lnwire.MilliSatoshi) {
	if b.lowerOK >= amt {
		b.lowerOK = 0
	}
	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}

	// A miss is strong evidence for the depleted mode. Preserve any
	// lower bound established by already-held shards.
	lowEstimate := amt / 8
	if lowEstimate < b.lowerOK {
		lowEstimate = b.lowerOK
	}
	if b.estimate == 0 || lowEstimate < b.estimate {
		b.estimate = lowEstimate
	}

	b.conf += 2.5
	if b.conf > 12 {
		b.conf = 12
	}
}

type rememberedNetwork struct {
	beliefs map[edgeKey]liquidityBelief
	lastNow time.Time
}

var candidateMemory = struct {
	sync.Mutex
	networks map[uint64]*rememberedNetwork
}{
	networks: make(map[uint64]*rememberedNetwork),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	beliefs      map[edgeKey]liquidityBelief
	used         map[edgeKey]lnwire.MilliSatoshi
	pathPenalty  map[edgeKey]float64
	policyBad    map[edgeKey]bool
	failedRoutes map[uint64]uint32

	delivered lnwire.MilliSatoshi
	committed bool
	graphSig  uint64
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]liquidityBelief),
		used:          make(map[edgeKey]lnwire.MilliSatoshi),
		pathPenalty:  make(map[edgeKey]float64),
		policyBad:    make(map[edgeKey]bool),
		failedRoutes: make(map[uint64]uint32),
		graphSig:     hashVertex(source),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edgeByKey[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], edge,
				)
				r.edgeByKey[key] = edge
				r.graphSig ^= edgeFingerprint(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	if r.graphSig == 0 {
		r.graphSig = 1
	}

	now := view.Now()

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.graphSig]
	if memory == nil || (!memory.lastNow.IsZero() &&
		now.Before(memory.lastNow)) {

		memory = &rememberedNetwork{
			beliefs: make(map[edgeKey]liquidityBelief),
		}
		candidateMemory.networks[r.graphSig] = memory
	}
	memory.lastNow = now
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func hashVertex(vertex route.Vertex) uint64 {
	const offset = uint64(1469598103934665603)
	const prime = uint64(1099511628211)

	hash := offset
	for _, value := range vertex {
		hash ^= uint64(value)
		hash *= prime
	}
	return hash
}

func mix64(value uint64) uint64 {
	value ^= value >> 30
	value *= 0xbf58476d1ce4e5b9
	value ^= value >> 27
	value *= 0x94d049bb133111eb
	return value ^ (value >> 31)
}

func edgeFingerprint(edge *candidateEdge) uint64 {
	value := edge.key.chanID * 0x9e3779b97f4a7c15
	value ^= hashVertex(edge.key.from)
	value ^= mix64(hashVertex(edge.key.to))
	value ^= mix64(uint64(edge.capacity))
	return mix64(value)
}

func clampProbability(probability float64) float64 {
	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.995 {
		return 0.995
	}
	return probability
}

func bimodalPrior(amt,
	capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)

	// The first term models the small depleted-side mode. The second
	// models the cliff near a nearly full channel.
	lowMode := 0.49 * math.Exp(-ratio/0.025)
	highMode := 0.49 / (1 + math.Exp((ratio-0.93)/0.025))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if totalAmt > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] >= totalAmt {
			return 0.995
		}
		return 0.005
	}

	prior := bimodalPrior(totalAmt, edge.capacity)
	belief := r.beliefs[edge.key]

	if belief.upperFail != 0 && totalAmt >= belief.upperFail {
		return 0.005
	}
	if belief.lowerOK != 0 && totalAmt <= belief.lowerOK {
		return 0.995
	}
	if belief.conf == 0 || belief.estimate == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1_000_000 {
		scale = 1_000_000
	}

	evidence := 1 / (1 + math.Exp(
		(float64(totalAmt)-float64(belief.estimate))/scale,
	))
	weight := belief.conf / (belief.conf + 3)

	return clampProbability((1-weight)*prior + weight*evidence)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
	path     []*candidateEdge
	index    int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].arriving < q[j].arriving
	}
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *dijkstraQueue) Push(value any) {
	item := value.(*dijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	old[last] = nil
	*q = old[:last]
	return item
}

func prependEdge(edge *candidateEdge,
	path []*candidateEdge) []*candidateEdge {

	result := make([]*candidateEdge, len(path)+1)
	result[0] = edge
	copy(result[1:], path)
	return result
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	best := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	queue := &dijkstraQueue{}
	heap.Push(queue, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*dijkstraItem)
		bestScore, ok := best[item.node]
		if !ok || item.score > bestScore+1e-12 {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(amt, item.path)
			if err != nil {
				return nil, 0, err
			}
			return rt, item.score, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			totalExposure := amtOver + r.used[edge.key]
			if totalExposure > edge.capacity {
				continue
			}

			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] < totalExposure {

				continue
			}

			probability := r.probability(edge, totalExposure)
			risk := -math.Log(probability)
			risk += r.pathPenalty[edge.key]

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			// Reliability dominates. Fees and hop count break ties
			// between similarly reliable paths.
			score := item.score + risk + 0.015 +
				float64(fee)/5_000_000

			oldScore, exists := best[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			best[edge.key.from] = score
			heap.Push(queue, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
				path:     prependEdge(edge, item.path),
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = uint32(40)

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("invalid route path")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			outgoingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(outgoingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := finalCltvDelta
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func routeEdgeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeEdges(rt *route.Route) (
	[]*candidateEdge, bool) {

	if rt == nil {
		return nil, false
	}

	edges := make([]*candidateEdge, len(rt.Hops))
	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgeByKey[key]
		if edge == nil {
			return nil, false
		}
		edges[i] = edge
		from = hop.PubKeyBytes
	}

	return edges, true
}

func routeFingerprint(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	hash := mix64(uint64(rt.TotalAmount))
	from := rt.SourcePubKey
	for _, hop := range rt.Hops {
		value := hop.ChannelID
		value ^= hashVertex(from)
		value ^= mix64(hashVertex(hop.PubKeyBytes))
		hash ^= mix64(value)
		from = hop.PubKeyBytes
	}
	return hash
}

func (r *candidateRouter) routeRisk(rt *route.Route) float64 {
	edges, ok := r.routeEdges(rt)
	if !ok {
		return math.Inf(1)
	}

	risk := 0.0
	for i, edge := range edges {
		amt := routeEdgeAmount(rt, i)
		total := amt + r.used[edge.key]
		risk -= math.Log(r.probability(edge, total))
		risk += r.pathPenalty[edge.key]
	}

	if count := r.failedRoutes[routeFingerprint(rt)]; count != 0 {
		risk += float64(count) * 0.75
	}

	return risk
}

func minimumShard(remaining lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts <= 1 {
		return remaining
	}

	divisor := lnwire.MilliSatoshi(parts)
	result := remaining / divisor
	if remaining%divisor != 0 {
		result++
	}
	if result < 1 {
		result = 1
	}
	return result
}

func (r *candidateRouter) chooseRoute(remaining lnwire.MilliSatoshi,
	partsLeft uint32, allowSmall bool) (*route.Route, error) {

	minShard := minimumShard(remaining, partsLeft)
	candidates := make([]lnwire.MilliSatoshi, 0, 16)
	seen := make(map[lnwire.MilliSatoshi]bool)

	addCandidate := func(amt lnwire.MilliSatoshi) {
		if amt < 1 || amt > remaining || seen[amt] {
			return
		}
		seen[amt] = true
		candidates = append(candidates, amt)
	}

	addCandidate(minShard)
	addCandidate(remaining)

	if remaining > minShard {
		span := remaining - minShard
		for i := int64(1); i < 12; i++ {
			addCandidate(minShard +
				span*lnwire.MilliSatoshi(i)/12)
		}
	}

	var bestRoute *route.Route
	bestQuality := math.Inf(-1)

	for _, shard := range candidates {
		rt, _, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		risk := r.routeRisk(rt)
		progress := math.Log(
			float64(shard) / float64(minShard),
		)
		fee := rt.TotalAmount - shard
		if fee < 0 {
			fee = 0
		}
		feeRatio := float64(fee) / float64(shard)

		quality := -risk + 0.72*progress - 3*feeRatio
		if quality > bestQuality ||
			(quality == bestQuality &&
				(bestRoute == nil ||
					shard > deliveredAmount(bestRoute))) {

			bestQuality = quality
			bestRoute = rt
		}
	}

	if bestRoute != nil || !allowSmall || partsLeft <= 1 {
		if bestRoute == nil {
			return nil, errors.New("no route found")
		}
		return bestRoute, nil
	}

	// A failed large shard can still reveal a useful lower range.
	// Permit one deliberately smaller shard rather than permanently
	// excluding the failed corridor.
	lower := minShard * 35 / 100
	if lower < 1 {
		lower = 1
	}

	for i := int64(0); i < 6; i++ {
		shard := lower
		if minShard > lower {
			shard += (minShard-lower)*
				lnwire.MilliSatoshi(i)/6
		}
		if shard >= minShard {
			continue
		}

		rt, _, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		risk := r.routeRisk(rt)
		fee := rt.TotalAmount - shard
		if fee < 0 {
			fee = 0
		}
		quality := -risk -
			0.35*math.Log(float64(minShard)/float64(shard)) -
			3*float64(fee)/float64(shard)

		if quality > bestQuality {
			bestQuality = quality
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}
	return bestRoute, nil
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	return r.chooseRoute(amt, partsLeft, true)
}

func (r *candidateRouter) observeLocalPass(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[edge.key]
	belief.observePass(totalAmt, edge.capacity)
	r.beliefs[edge.key] = belief
}

func (r *candidateRouter) observeLocalFail(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) {

	belief := r.beliefs[edge.key]
	belief.observeFail(totalAmt)
	r.beliefs[edge.key] = belief
}

func (r *candidateRouter) rememberFailure(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) {

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.graphSig]
	if memory == nil {
		memory = &rememberedNetwork{
			beliefs: make(map[edgeKey]liquidityBelief),
		}
		candidateMemory.networks[r.graphSig] = memory
	}

	belief := memory.beliefs[edge.key]
	belief.observeFail(totalAmt)
	memory.beliefs[edge.key] = belief
	candidateMemory.Unlock()
}

func subtractFloor(value,
	spent lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= spent {
		return 0
	}
	return value - spent
}

func (r *candidateRouter) commitPayment() {
	if r.committed {
		return
	}
	r.committed = true

	candidateMemory.Lock()
	defer candidateMemory.Unlock()

	memory := candidateMemory.networks[r.graphSig]
	if memory == nil {
		memory = &rememberedNetwork{
			beliefs: make(map[edgeKey]liquidityBelief),
		}
		candidateMemory.networks[r.graphSig] = memory
	}

	for key, spent := range r.used {
		edge := r.edgeByKey[key]
		if edge == nil || spent <= 0 {
			continue
		}

		before := r.beliefs[key]
		after := liquidityBelief{
			lowerOK: subtractFloor(before.lowerOK, spent),
			conf:    before.conf,
		}

		if before.upperFail > spent {
			after.upperFail = before.upperFail - spent
			after.estimate = after.upperFail / 8
			if after.estimate < after.lowerOK {
				after.estimate = after.lowerOK
			}
		} else {
			after.estimate = subtractFloor(
				edge.capacity*9/10, spent,
			)
		}

		if after.conf < 2 {
			after.conf = 2
		}
		memory.beliefs[key] = after
	}
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) penalizeUnknownPath(
	edges []*candidateEdge) {

	for _, edge := range edges {
		if edge.key.from == r.source {
			continue
		}
		r.pathPenalty[edge.key] += 0.8
		if r.pathPenalty[edge.key] > 12 {
			r.pathPenalty[edge.key] = 12
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	edges, ok := r.routeEdges(rt)
	if !ok {
		return nil
	}

	if result.Failure == nil {
		for i, edge := range edges {
			shardAmt := routeEdgeAmount(rt, i)
			totalAmt := r.used[edge.key] + shardAmt
			r.observeLocalPass(edge, totalAmt)
			r.used[edge.key] += shardAmt

			r.pathPenalty[edge.key] *= 0.35
			if r.pathPenalty[edge.key] < 0.01 {
				delete(r.pathPenalty, edge.key)
			}
		}

		r.delivered += deliveredAmount(rt)
		if r.delivered >= r.spec.Amount {
			r.commitPayment()
		}
		return nil
	}

	r.failedRoutes[routeFingerprint(rt)]++

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)

	// Every channel before the failing node demonstrably forwarded
	// this attempt, even though the attempt did not settle.
	if failIndex >= 0 {
		passCount := failIndex
		if passCount > len(edges) {
			passCount = len(edges)
		}
		for i := 0; i < passCount; i++ {
			edge := edges[i]
			totalAmt := r.used[edge.key] +
				routeEdgeAmount(rt, i)
			r.observeLocalPass(edge, totalAmt)
		}
	}

	if failIndex < 0 || failIndex >= len(edges) {
		r.penalizeUnknownPath(edges)
		return nil
	}

	failedEdge := edges[failIndex]
	totalAmt := r.used[failedEdge.key] +
		routeEdgeAmount(rt, failIndex)

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.observeLocalFail(failedEdge, totalAmt)
		r.rememberFailure(failedEdge, totalAmt)
		r.pathPenalty[failedEdge.key] += 3

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[failedEdge.key] = true

	default:
		r.pathPenalty[failedEdge.key] += 1.5
	}

	if r.pathPenalty[failedEdge.key] > 16 {
		r.pathPenalty[failedEdge.key] = 16
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi,
	checkMin bool) bool {

	if checkMin && amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     uint8
}

var candidateSharedState = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	shared  map[candidateEdgeKey]candidateBelief
	current map[candidateEdgeKey]candidateBelief

	reserved   map[candidateEdgeKey]lnwire.MilliSatoshi
	edgePenalty map[candidateEdgeKey]float64
	policyBad  map[candidateEdgeKey]bool

	plan []*route.Route
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		shared:        make(map[candidateEdgeKey]candidateBelief),
		current:       make(map[candidateEdgeKey]candidateBelief),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		policyBad:     make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateSharedState.Lock()
	for key := range r.edges {
		if belief, ok := candidateSharedState.beliefs[key]; ok {
			r.shared[key] = belief
		}
	}
	candidateSharedState.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-ratio/0.025)
	highMode := 0.5 / (1 + math.Exp((ratio-0.93)/0.04))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateEvidenceProbability(b candidateBelief,
	amt, capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.005
	}

	if b.lowerOK > 0 && b.upperBad > b.lowerOK {
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(amt-b.lowerOK) / width
		p := 0.99 - 0.98*pos
		if p < 0.01 {
			return 0.01
		}
		if p > 0.99 {
			return 0.99
		}
		return p
	}

	if b.upperBad > 0 {
		ratio := float64(amt) / float64(b.upperBad)
		p := 0.02 + 0.90*math.Exp(-ratio/0.12)
		if p > 0.99 {
			return 0.99
		}
		return p
	}

	if b.lowerOK > 0 {
		if capacity <= b.lowerOK {
			return 0.985
		}
		distance := float64(amt-b.lowerOK) / float64(capacity)
		p := 0.58 + 0.40*math.Exp(-distance/0.20)
		if p > 0.99 {
			return 0.99
		}
		return p
	}

	return candidatePrior(amt, capacity)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	p := candidatePrior(total, edge.capacity)

	if belief, ok := r.shared[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 1.5)
		if weight > 0.92 {
			weight = 0.92
		}
		p = p*(1-weight) + evidence*weight
	}

	if belief, ok := r.current[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		p = 0.04*p + 0.96*evidence
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func candidateUpdateBelief(b candidateBelief,
	amt lnwire.MilliSatoshi, passed bool) candidateBelief {

	if passed {
		if b.upperBad > 0 && amt >= b.upperBad {
			b.upperBad = 0
			b.conf /= 2
		}
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
	} else {
		if b.lowerOK > 0 && amt <= b.lowerOK {
			b.lowerOK = 0
			b.conf /= 2
		}
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
	}

	if b.conf < 16 {
		b.conf++
	}
	return b
}

func (r *candidateRouter) learn(key candidateEdgeKey,
	currentAmt, sharedAmt lnwire.MilliSatoshi, passed bool) {

	r.current[key] = candidateUpdateBelief(
		r.current[key], currentAmt, passed,
	)
	r.shared[key] = candidateUpdateBelief(
		r.shared[key], sharedAmt, passed,
	)

	candidateSharedState.Lock()
	candidateSharedState.beliefs[key] = candidateUpdateBelief(
		candidateSharedState.beliefs[key], sharedAmt, passed,
	)
	candidateSharedState.Unlock()
}

func (r *candidateRouter) hardTotal(edge *candidateEdge) lnwire.MilliSatoshi {
	limit := edge.capacity

	if edge.key.from == r.source {
		local := r.localBalances[edge.key.chanID]
		if local < limit {
			limit = local
		}
	}

	if belief, ok := r.current[edge.key]; ok &&
		belief.upperBad > 0 {

		bound := belief.upperBad - 1
		if bound < 0 {
			bound = 0
		}
		if bound < limit {
			limit = bound
		}
	}

	return limit
}

func candidateRecommendedFromBelief(b candidateBelief,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	var result lnwire.MilliSatoshi

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		result = b.lowerOK + (b.upperBad-b.lowerOK)/4

	case b.upperBad > 0:
		result = b.upperBad * 58 / 100

	case b.lowerOK > 0:
		result = capacity * 88 / 100
		if b.lowerOK > result {
			result = b.lowerOK
		}

	default:
		result = capacity * 78 / 100
	}

	capLimit := capacity * 98 / 100
	if result > capLimit {
		result = capLimit
	}
	return result
}

func (r *candidateRouter) recommendedTotal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	hard := r.hardTotal(edge)
	if edge.key.from == r.source {
		return hard
	}

	var result lnwire.MilliSatoshi
	if belief, ok := r.current[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else if belief, ok := r.shared[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else {
		result = edge.capacity * 78 / 100
	}

	if result > hard {
		result = hard
	}
	return result
}

type candidateQueueItem struct {
	node     route.Vertex
	cost     float64
	arriving lnwire.MilliSatoshi
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64) ([]*candidateEdge, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	dist := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	pq := &candidateQueue{}
	heap.Push(pq, &candidateQueueItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateQueueItem)
		best, ok := dist[item.node]
		if !ok || item.cost > best {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				!edge.usable(item.arriving, true) {

				continue
			}

			total := item.arriving + r.reserved[edge.key]
			if total > r.hardTotal(edge) {
				continue
			}

			probability := r.edgeProbability(edge, total)
			riskCost := -math.Log(probability) * 900_000
			edgeCost := riskCost + 2_000 +
				r.edgePenalty[edge.key] + diversity[edge.key]

			sending := item.arriving
			if edge.key.from != r.source {
				fee := edge.fee(item.arriving)
				sending += fee
				edgeCost += float64(fee)
			}

			newCost := item.cost + edgeCost
			oldCost, exists := dist[edge.key.from]
			if exists && newCost >= oldCost {
				continue
			}

			dist[edge.key.from] = newCost
			next[edge.key.from] = edge
			heap.Push(pq, &candidateQueueItem{
				node:     edge.key.from,
				cost:     newCost,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("routing cycle")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	return path, nil
}

func candidateSamePath(a, b []*candidateEdge) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].key != b[i].key {
			return false
		}
	}
	return true
}

func candidatePathAmounts(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	amounts := make([]lnwire.MilliSatoshi, len(path))
	if len(path) == 0 {
		return amounts
	}

	amounts[len(path)-1] = finalAmt
	for i := len(path) - 2; i >= 0; i-- {
		next := path[i+1]
		amounts[i] = amounts[i+1] + next.fee(amounts[i+1])
	}
	return amounts
}

func (r *candidateRouter) pathWithin(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe, checkMin bool) bool {

	if finalAmt <= 0 || len(path) == 0 {
		return false
	}

	amounts := candidatePathAmounts(path, finalAmt)
	for i, edge := range path {
		if !edge.usable(amounts[i], checkMin) {
			return false
		}

		limit := r.hardTotal(edge)
		if safe {
			limit = r.recommendedTotal(edge)
		}

		total := amounts[i] + r.reserved[edge.key] +
			planned[edge.key]
		if total > limit {
			return false
		}
	}

	return true
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	want lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe bool) lnwire.MilliSatoshi {

	if want <= 0 {
		return 0
	}

	var low lnwire.MilliSatoshi
	high := want

	for low < high {
		mid := low + (high-low+1)/2
		if r.pathWithin(path, mid, planned, safe, false) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	if low == 0 ||
		!r.pathWithin(path, low, planned, safe, true) {

		return 0
	}
	return low
}

func (r *candidateRouter) pathScore(path []*candidateEdge,
	amt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	remaining lnwire.MilliSatoshi) float64 {

	amounts := candidatePathAmounts(path, amt)
	logProbability := 0.0

	for i, edge := range path {
		total := amounts[i] + r.reserved[edge.key] +
			planned[edge.key]
		logProbability += math.Log(r.edgeProbability(edge, total))
	}

	coverage := float64(amt) / float64(remaining)
	if coverage > 1 {
		coverage = 1
	}
	fee := amounts[0] - amt

	return 4*math.Log(coverage) + 0.8*logProbability -
		float64(fee)/5_000_000 - 0.03*float64(len(path))
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	amounts := candidatePathAmounts(path, amt)
	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forwardAmt = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateAddPlanned(path []*candidateEdge,
	amt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		planned[edge.key] += amounts[i]
	}
}

func (r *candidateRouter) allocatePlan(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int,
	safe bool) ([]*route.Route, bool) {

	remaining := amt
	planned := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	result := make([]*route.Route, 0, parts)

	for len(result) < parts && remaining > 0 {
		bestIdx := -1
		var bestAmount lnwire.MilliSatoshi
		bestScore := math.Inf(-1)

		for i, path := range paths {
			maxAmount := r.maxPathAmount(
				path, remaining, planned, safe,
			)
			if maxAmount == 0 {
				continue
			}

			score := r.pathScore(
				path, maxAmount, planned, remaining,
			)
			if score > bestScore {
				bestIdx = i
				bestAmount = maxAmount
				bestScore = score
			}
		}

		if bestIdx < 0 {
			break
		}

		path := paths[bestIdx]
		rt, err := r.buildRoute(path, bestAmount)
		if err != nil {
			break
		}

		result = append(result, rt)
		candidateAddPlanned(path, bestAmount, planned)
		remaining -= bestAmount
	}

	return result, remaining == 0
}

func candidateAppendProbe(probes []lnwire.MilliSatoshi,
	probe lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if probe <= 0 {
		return probes
	}
	for _, existing := range probes {
		if existing == probe {
			return probes
		}
	}
	return append(probes, probe)
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts int) ([]*route.Route, error) {

	if parts < 1 {
		return nil, errors.New("maximum parts reached")
	}

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var probes []lnwire.MilliSatoshi
	probes = candidateAppendProbe(probes, amt)
	probes = candidateAppendProbe(probes, base)
	probes = candidateAppendProbe(probes, base*3/4)
	probes = candidateAppendProbe(probes, base/2)
	probes = candidateAppendProbe(probes, base/4)
	probes = candidateAppendProbe(probes, base/8)

	rounds := parts + 2
	if rounds > 10 {
		rounds = 10
	}

	var paths [][]*candidateEdge
	for _, probe := range probes {
		diversity := make(map[candidateEdgeKey]float64)

		for i := 0; i < rounds; i++ {
			path, err := r.findPath(probe, diversity)
			if err != nil {
				break
			}

			duplicate := false
			for _, existing := range paths {
				if candidateSamePath(existing, path) {
					duplicate = true
					break
				}
			}
			if !duplicate {
				paths = append(paths, path)
			}

			for _, edge := range path {
				diversity[edge.key] += 2_500_000
			}
		}
	}

	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}

	if plan, ok := r.allocatePlan(paths, amt, parts, true); ok {
		return plan, nil
	}
	if plan, ok := r.allocatePlan(paths, amt, parts, false); ok {
		return plan, nil
	}

	return nil, errors.New("no route set can carry payment")
}

func candidateDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}

	if len(r.plan) != 0 {
		next := r.plan[0]
		if candidateDelivered(next) <= amt {
			r.plan = r.plan[1:]
			return next, nil
		}
		r.plan = nil
	}

	partsLeft := int(maxParts - inFlightHtlcs)
	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	r.plan = plan[1:]
	return plan[0], nil
}

func candidateRouteEdge(rt *route.Route,
	index int) candidateEdgeKey {

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) learnRoutePassed(rt *route.Route,
	end int, reserve bool) {

	if end > len(rt.Hops) {
		end = len(rt.Hops)
	}

	for i := 0; i < end; i++ {
		key := candidateRouteEdge(rt, i)
		amt := candidateRouteAmount(rt, i)
		total := amt + r.reserved[key]
		r.learn(key, total, amt, true)
	}

	if reserve {
		for i := 0; i < end; i++ {
			key := candidateRouteEdge(rt, i)
			r.reserved[key] += candidateRouteAmount(rt, i)
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.learnRoutePassed(rt, len(rt.Hops), true)
		return nil
	}

	r.plan = nil
	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex > 0 {
		r.learnRoutePassed(rt, failIndex, false)
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key := candidateRouteEdge(rt, i)
			r.edgePenalty[key] += 450_000
		}
		return nil
	}

	key := candidateRouteEdge(rt, failIndex)
	amt := candidateRouteAmount(rt, failIndex)
	total := amt + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learn(key, total, amt, false)
		r.edgePenalty[key] += 700_000

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[key] = true

	default:
		r.edgePenalty[key] += 1_500_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi,
	checkMin bool) bool {

	if checkMin && amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     uint8
}

var candidateSharedState = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	shared  map[candidateEdgeKey]candidateBelief
	current map[candidateEdgeKey]candidateBelief

	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	edgePenalty   map[candidateEdgeKey]float64
	liquidityFail map[candidateEdgeKey]uint8
	policyBad     map[candidateEdgeKey]bool
	failedRoutes  map[uint64]uint8

	plan     []*route.Route
	attempts int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		shared:         make(map[candidateEdgeKey]candidateBelief),
		current:        make(map[candidateEdgeKey]candidateBelief),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:    make(map[candidateEdgeKey]float64),
		liquidityFail:  make(map[candidateEdgeKey]uint8),
		policyBad:      make(map[candidateEdgeKey]bool),
		failedRoutes:   make(map[uint64]uint8),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateSharedState.Lock()
	for key := range r.edges {
		if belief, ok := candidateSharedState.beliefs[key]; ok {
			r.shared[key] = belief
		}
	}
	candidateSharedState.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-ratio/0.025)
	highMode := 0.5 / (1 + math.Exp((ratio-0.93)/0.04))
	p := lowMode + highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateEvidenceProbability(b candidateBelief,
	amt, capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.005
	}

	if b.lowerOK > 0 && b.upperBad > b.lowerOK {
		width := float64(b.upperBad - b.lowerOK)
		pos := float64(amt-b.lowerOK) / width
		p := 0.99 - 0.98*pos
		if p < 0.01 {
			return 0.01
		}
		if p > 0.99 {
			return 0.99
		}
		return p
	}

	if b.upperBad > 0 {
		ratio := float64(amt) / float64(b.upperBad)
		p := 0.015 + 0.92*math.Exp(-ratio/0.16)
		if p > 0.99 {
			return 0.99
		}
		return p
	}

	if b.lowerOK > 0 {
		if capacity <= b.lowerOK {
			return 0.985
		}
		distance := float64(amt-b.lowerOK) / float64(capacity)
		p := 0.60 + 0.38*math.Exp(-distance/0.20)
		if p > 0.99 {
			return 0.99
		}
		return p
	}

	return candidatePrior(amt, capacity)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	p := candidatePrior(total, edge.capacity)

	if belief, ok := r.shared[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 1.75)
		if weight > 0.90 {
			weight = 0.90
		}
		p = p*(1-weight) + evidence*weight
	}

	if belief, ok := r.current[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		p = 0.03*p + 0.97*evidence
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func candidateUpdateBelief(b candidateBelief,
	amt lnwire.MilliSatoshi, passed bool) candidateBelief {

	if passed {
		if b.upperBad > 0 && amt >= b.upperBad {
			b.upperBad = 0
			b.conf /= 2
		}
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
	} else {
		if b.lowerOK > 0 && amt <= b.lowerOK {
			b.lowerOK = 0
			b.conf /= 2
		}
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
	}

	if b.conf < 16 {
		b.conf++
	}
	return b
}

func (r *candidateRouter) learn(key candidateEdgeKey,
	currentAmt, sharedAmt lnwire.MilliSatoshi, passed bool) {

	r.current[key] = candidateUpdateBelief(
		r.current[key], currentAmt, passed,
	)
	r.shared[key] = candidateUpdateBelief(
		r.shared[key], sharedAmt, passed,
	)

	candidateSharedState.Lock()
	candidateSharedState.beliefs[key] = candidateUpdateBelief(
		candidateSharedState.beliefs[key], sharedAmt, passed,
	)
	candidateSharedState.Unlock()

	if passed {
		r.liquidityFail[key] = 0
		r.edgePenalty[key] *= 0.35
	}
}

func candidateRetryLimit(b candidateBelief) lnwire.MilliSatoshi {
	if b.upperBad <= 0 {
		return 0
	}

	if b.lowerOK > 0 && b.lowerOK < b.upperBad {
		gap := b.upperBad - b.lowerOK
		return b.lowerOK + gap*2/3
	}

	return b.upperBad * 58 / 100
}

func (r *candidateRouter) hardTotal(edge *candidateEdge) lnwire.MilliSatoshi {
	limit := edge.capacity

	if edge.key.from == r.source {
		local := r.localBalances[edge.key.chanID]
		if local < limit {
			limit = local
		}
	}

	if belief, ok := r.current[edge.key]; ok &&
		belief.upperBad > 0 {

		bound := candidateRetryLimit(belief)
		if bound < limit {
			limit = bound
		}
	}

	return limit
}

func candidateRecommendedFromBelief(b candidateBelief,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	var result lnwire.MilliSatoshi

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		result = b.lowerOK + (b.upperBad-b.lowerOK)/3

	case b.upperBad > 0:
		result = b.upperBad * 58 / 100

	case b.lowerOK > 0:
		result = capacity * 88 / 100
		if b.lowerOK > result {
			result = b.lowerOK
		}

	default:
		result = capacity * 78 / 100
	}

	capLimit := capacity * 98 / 100
	if result > capLimit {
		result = capLimit
	}
	return result
}

func (r *candidateRouter) recommendedTotal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	hard := r.hardTotal(edge)
	if edge.key.from == r.source {
		return hard
	}

	var result lnwire.MilliSatoshi
	if belief, ok := r.current[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else if belief, ok := r.shared[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else {
		result = edge.capacity * 78 / 100
	}

	if result > hard {
		result = hard
	}
	return result
}

func (r *candidateRouter) edgeBlocked(edge *candidateEdge) bool {
	if r.policyBad[edge.key] {
		return true
	}

	failures := r.liquidityFail[edge.key]
	if failures < 5 {
		return false
	}

	belief := r.current[edge.key]
	return belief.lowerOK == 0
}

type candidateQueueItem struct {
	node     route.Vertex
	cost     float64
	arriving lnwire.MilliSatoshi
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64,
	checkMin bool) ([]*candidateEdge, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	dist := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	pq := &candidateQueue{}
	heap.Push(pq, &candidateQueueItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateQueueItem)
		best, ok := dist[item.node]
		if !ok || item.cost > best {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.edgeBlocked(edge) ||
				!edge.usable(item.arriving, checkMin) {

				continue
			}

			total := item.arriving + r.reserved[edge.key]
			if total > r.hardTotal(edge) {
				continue
			}

			probability := r.edgeProbability(edge, total)
			riskCost := -math.Log(probability) * 825_000
			failCost := float64(r.liquidityFail[edge.key]) *
				350_000
			edgeCost := riskCost + 3_000 +
				failCost + r.edgePenalty[edge.key] +
				diversity[edge.key]

			sending := item.arriving
			if edge.key.from != r.source {
				fee := edge.fee(item.arriving)
				sending += fee
				edgeCost += float64(fee)
			}

			newCost := item.cost + edgeCost
			oldCost, exists := dist[edge.key.from]
			if exists && newCost >= oldCost {
				continue
			}

			dist[edge.key.from] = newCost
			next[edge.key.from] = edge
			heap.Push(pq, &candidateQueueItem{
				node:     edge.key.from,
				cost:     newCost,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("routing cycle")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	return path, nil
}

func candidateSamePath(a, b []*candidateEdge) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].key != b[i].key {
			return false
		}
	}
	return true
}

func candidatePathAmounts(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	amounts := make([]lnwire.MilliSatoshi, len(path))
	if len(path) == 0 {
		return amounts
	}

	amounts[len(path)-1] = finalAmt
	for i := len(path) - 2; i >= 0; i-- {
		next := path[i+1]
		amounts[i] = amounts[i+1] + next.fee(amounts[i+1])
	}
	return amounts
}

func (r *candidateRouter) pathWithin(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe, checkMin bool) bool {

	if finalAmt <= 0 || len(path) == 0 {
		return false
	}

	amounts := candidatePathAmounts(path, finalAmt)
	for i, edge := range path {
		if r.edgeBlocked(edge) ||
			!edge.usable(amounts[i], checkMin) {

			return false
		}

		limit := r.hardTotal(edge)
		if safe {
			limit = r.recommendedTotal(edge)
		}

		total := amounts[i] + r.reserved[edge.key] +
			planned[edge.key]
		if total > limit {
			return false
		}
	}

	return true
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	want lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe bool) lnwire.MilliSatoshi {

	if want <= 0 {
		return 0
	}

	var low lnwire.MilliSatoshi
	high := want

	for low < high {
		mid := low + (high-low+1)/2
		if r.pathWithin(path, mid, planned, safe, false) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	if low == 0 ||
		!r.pathWithin(path, low, planned, safe, true) {

		return 0
	}

	return low
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	amounts := candidatePathAmounts(path, amt)
	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forwardAmt = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateAddPlanned(path []*candidateEdge,
	amt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		planned[edge.key] += amounts[i]
	}
}

func candidateClonePlanned(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, value := range source {
		result[key] = value
	}
	return result
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amt <= 0 {
		return amounts
	}
	for _, existing := range amounts {
		if existing == amt {
			return amounts
		}
	}
	return append(amounts, amt)
}

type candidatePlanPiece struct {
	path []*candidateEdge
	amt  lnwire.MilliSatoshi
}

type candidatePlanState struct {
	pieces    []candidatePlanPiece
	planned   map[candidateEdgeKey]lnwire.MilliSatoshi
	remaining lnwire.MilliSatoshi
	lastPath  int
	rank      float64
}

func (r *candidateRouter) planQuality(state *candidatePlanState,
	original lnwire.MilliSatoshi, complete bool) float64 {

	logProbability := 0.0
	for key, amount := range state.planned {
		edge := r.edges[key]
		if edge == nil {
			continue
		}
		total := amount + r.reserved[key]
		logProbability += math.Log(r.edgeProbability(edge, total))
	}

	var fees lnwire.MilliSatoshi
	hops := 0
	for _, piece := range state.pieces {
		amounts := candidatePathAmounts(piece.path, piece.amt)
		if len(amounts) != 0 {
			fees += amounts[0] - piece.amt
		}
		hops += len(piece.path)
	}

	partCost := 0.10 * float64(len(state.pieces))
	hopCost := 0.018 * float64(hops)
	feeCost := float64(fees) / 2_500_000

	if complete {
		return 3.0*logProbability - feeCost -
			hopCost - partCost
	}

	covered := float64(original-state.remaining) / float64(original)
	return 250*covered + 1.6*logProbability -
		feeCost - hopCost - partCost
}

func (r *candidateRouter) stateRoutes(
	state *candidatePlanState) ([]*route.Route, error) {

	result := make([]*route.Route, 0, len(state.pieces))
	for _, piece := range state.pieces {
		rt, err := r.buildRoute(piece.path, piece.amt)
		if err != nil {
			return nil, err
		}
		result = append(result, rt)
	}
	return result, nil
}

func (r *candidateRouter) beamPlan(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int,
	safe bool) ([]*route.Route, bool) {

	if parts < 1 {
		return nil, false
	}

	beam := []*candidatePlanState{{
		planned:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		remaining: amt,
	}}

	var best *candidatePlanState
	bestQuality := math.Inf(-1)

	for depth := 0; depth < parts && len(beam) != 0; depth++ {
		var expanded []*candidatePlanState

		for _, state := range beam {
			slots := parts - len(state.pieces)
			if slots <= 0 {
				continue
			}

			average := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			for pathIndex := state.lastPath;
				pathIndex < len(paths); pathIndex++ {

				path := paths[pathIndex]
				maxAmount := r.maxPathAmount(
					path, state.remaining,
					state.planned, safe,
				)
				if maxAmount == 0 {
					continue
				}

				var choices []lnwire.MilliSatoshi
				choices = candidateAppendAmount(
					choices, maxAmount,
				)
				if average <= maxAmount {
					choices = candidateAppendAmount(
						choices, average,
					)
				}
				choices = candidateAppendAmount(
					choices, maxAmount*3/4,
				)
				choices = candidateAppendAmount(
					choices, maxAmount/2,
				)

				for _, shard := range choices {
					if shard > state.remaining ||
						!r.pathWithin(
							path, shard, state.planned,
							safe, true,
						) {

						continue
					}

					planned := candidateClonePlanned(
						state.planned,
					)
					candidateAddPlanned(path, shard, planned)

					pieces := append(
						[]candidatePlanPiece(nil),
						state.pieces...,
					)
					pieces = append(pieces, candidatePlanPiece{
						path: path,
						amt:  shard,
					})

					next := &candidatePlanState{
						pieces:    pieces,
						planned:   planned,
						remaining: state.remaining - shard,
						lastPath:  pathIndex,
					}

					if next.remaining == 0 {
						quality := r.planQuality(
							next, amt, true,
						)
						if quality > bestQuality {
							best = next
							bestQuality = quality
						}
						continue
					}

					next.rank = r.planQuality(
						next, amt, false,
					)
					expanded = append(expanded, next)
				}
			}
		}

		sort.Slice(expanded, func(i, j int) bool {
			return expanded[i].rank > expanded[j].rank
		})
		if len(expanded) > 72 {
			expanded = expanded[:72]
		}
		beam = expanded
	}

	if best == nil {
		return nil, false
	}

	routes, err := r.stateRoutes(best)
	if err != nil {
		return nil, false
	}
	return routes, true
}

func (r *candidateRouter) fallbackRoute(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int) (*route.Route, error) {

	if parts < 1 {
		return nil, errors.New("maximum parts reached")
	}

	needed := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)
	planned := make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	var bestPath []*candidateEdge
	var bestAmount lnwire.MilliSatoshi
	bestScore := math.Inf(-1)

	for _, path := range paths {
		hard := r.maxPathAmount(path, amt, planned, false)
		if hard < needed {
			continue
		}

		safe := r.maxPathAmount(path, amt, planned, true)
		shard := hard
		if safe >= needed {
			shard = safe
		}

		amounts := candidatePathAmounts(path, shard)
		logProbability := 0.0
		for i, edge := range path {
			total := amounts[i] + r.reserved[edge.key]
			logProbability += math.Log(
				r.edgeProbability(edge, total),
			)
		}

		coverage := float64(shard) / float64(amt)
		fee := amounts[0] - shard
		score := 2.5*logProbability + 4*coverage -
			float64(fee)/2_500_000 -
			0.025*float64(len(path))

		if score > bestScore {
			bestScore = score
			bestPath = path
			bestAmount = shard
		}
	}

	if bestPath == nil {
		return nil, errors.New("no route set can carry payment")
	}
	return r.buildRoute(bestPath, bestAmount)
}

func (r *candidateRouter) collectPaths(
	amt lnwire.MilliSatoshi, parts int) [][]*candidateEdge {

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var probes []lnwire.MilliSatoshi
	probes = candidateAppendAmount(probes, amt)
	probes = candidateAppendAmount(probes, base)
	probes = candidateAppendAmount(probes, base*3/4)
	probes = candidateAppendAmount(probes, base/2)
	probes = candidateAppendAmount(probes, base/4)
	probes = candidateAppendAmount(probes, base/8)
	probes = candidateAppendAmount(probes, base/16)
	probes = candidateAppendAmount(probes, 1)

	rounds := parts + 3
	if rounds < 6 {
		rounds = 6
	}
	if rounds > 12 {
		rounds = 12
	}

	var paths [][]*candidateEdge
	for _, probe := range probes {
		diversity := make(map[candidateEdgeKey]float64)
		checkMin := probe != 1

		for i := 0; i < rounds; i++ {
			path, err := r.findPath(
				probe, diversity, checkMin,
			)
			if err != nil {
				break
			}

			duplicate := false
			for _, existing := range paths {
				if candidateSamePath(existing, path) {
					duplicate = true
					break
				}
			}
			if !duplicate {
				paths = append(paths, path)
				if len(paths) >= 96 {
					return paths
				}
			}

			for _, edge := range path {
				diversity[edge.key] += 1_800_000
			}
		}
	}

	return paths
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts int) ([]*route.Route, error) {

	if parts < 1 {
		return nil, errors.New("maximum parts reached")
	}

	paths := r.collectPaths(amt, parts)
	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}

	if plan, ok := r.beamPlan(paths, amt, parts, true); ok {
		return plan, nil
	}
	if plan, ok := r.beamPlan(paths, amt, parts, false); ok {
		return plan, nil
	}

	fallback, err := r.fallbackRoute(paths, amt, parts)
	if err != nil {
		return nil, err
	}
	return []*route.Route{fallback}, nil
}

func candidateDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	hash := uint64(1469598103934665603)
	mix := func(value uint64) {
		hash ^= value
		hash *= 1099511628211
	}

	mix(uint64(rt.TotalAmount))
	for i, hop := range rt.Hops {
		mix(hop.ChannelID)
		mix(uint64(candidateRouteAmount(rt, i)))
	}
	return hash
}

func (r *candidateRouter) attemptLimit(maxParts uint32) int {
	limit := 24 + 6*int(maxParts)
	if limit < 48 {
		limit = 48
	}
	if limit > 96 {
		limit = 96
	}
	return limit
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}
	if r.attempts >= r.attemptLimit(maxParts) {
		return nil, errors.New("routing attempt limit reached")
	}

	for replan := 0; replan < 6; replan++ {
		var next *route.Route

		if len(r.plan) != 0 {
			next = r.plan[0]
			r.plan = r.plan[1:]
			if candidateDelivered(next) > amt {
				r.plan = nil
				next = nil
			}
		}

		if next == nil {
			partsLeft := int(maxParts - inFlightHtlcs)
			plan, err := r.makePlan(amt, partsLeft)
			if err != nil {
				return nil, err
			}
			next = plan[0]
			r.plan = plan[1:]
		}

		hash := candidateRouteHash(next)
		if r.failedRoutes[hash] == 0 {
			r.attempts++
			return next, nil
		}

		for i := range next.Hops {
			key := candidateRouteEdge(next, i)
			r.edgePenalty[key] += 300_000
		}
		r.plan = nil
	}

	return nil, errors.New("no untried route found")
}

func candidateRouteEdge(rt *route.Route,
	index int) candidateEdgeKey {

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) learnRoutePassed(rt *route.Route,
	end int, reserve bool) {

	if end > len(rt.Hops) {
		end = len(rt.Hops)
	}

	for i := 0; i < end; i++ {
		key := candidateRouteEdge(rt, i)
		amt := candidateRouteAmount(rt, i)
		total := amt + r.reserved[key]
		r.learn(key, total, amt, true)
	}

	if reserve {
		for i := 0; i < end; i++ {
			key := candidateRouteEdge(rt, i)
			r.reserved[key] += candidateRouteAmount(rt, i)
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	hash := candidateRouteHash(rt)

	if result.Failure == nil {
		delete(r.failedRoutes, hash)
		r.learnRoutePassed(rt, len(rt.Hops), true)
		return nil
	}

	r.failedRoutes[hash]++
	r.plan = nil

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex > 0 {
		r.learnRoutePassed(rt, failIndex, false)
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key := candidateRouteEdge(rt, i)
			r.edgePenalty[key] += 600_000
		}
		return nil
	}

	key := candidateRouteEdge(rt, failIndex)
	amt := candidateRouteAmount(rt, failIndex)
	total := amt + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learn(key, total, amt, false)
		if r.liquidityFail[key] < 255 {
			r.liquidityFail[key]++
		}
		r.edgePenalty[key] += 900_000 +
			350_000*float64(r.liquidityFail[key])

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[key] = true

	default:
		r.edgePenalty[key] += 1_750_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateMaxAttempts    = 72
)

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi,
	checkMin bool) bool {

	if amt <= 0 {
		return false
	}
	if checkMin && amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return amt <= e.capacity
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     uint8
}

var candidateSharedState = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	shared  map[candidateEdgeKey]candidateBelief
	current map[candidateEdgeKey]candidateBelief

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	edgePenalty map[candidateEdgeKey]float64
	policyBad   map[candidateEdgeKey]bool

	plan     []*route.Route
	attempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		shared:        make(map[candidateEdgeKey]candidateBelief),
		current:       make(map[candidateEdgeKey]candidateBelief),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		policyBad:     make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateSharedState.Lock()
	for key := range r.edges {
		if belief, ok := candidateSharedState.beliefs[key]; ok {
			r.shared[key] = belief
		}
	}
	candidateSharedState.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-ratio/0.025)
	highMode := 0.5 / (1 + math.Exp((ratio-0.93)/0.04))
	probability := lowMode + highMode

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.985 {
		return 0.985
	}
	return probability
}

func candidateEvidenceProbability(b candidateBelief,
	amt, capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.005
	}

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		position := float64(amt-b.lowerOK) /
			float64(b.upperBad-b.lowerOK)
		probability := 0.99 - 0.98*position
		if probability < 0.01 {
			return 0.01
		}
		if probability > 0.99 {
			return 0.99
		}
		return probability

	case b.upperBad > 0:
		ratio := float64(amt) / float64(b.upperBad)
		probability := 0.02 + 0.90*math.Exp(-ratio/0.12)
		if probability > 0.99 {
			return 0.99
		}
		return probability

	case b.lowerOK > 0:
		if capacity <= b.lowerOK {
			return 0.985
		}
		distance := float64(amt-b.lowerOK) / float64(capacity)
		probability := 0.58 + 0.40*math.Exp(-distance/0.20)
		if probability > 0.99 {
			return 0.99
		}
		return probability
	}

	return candidatePrior(amt, capacity)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	probability := candidatePrior(total, edge.capacity)

	if belief, ok := r.shared[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 2.0)
		if weight > 0.86 {
			weight = 0.86
		}
		probability = probability*(1-weight) + evidence*weight
	}

	if belief, ok := r.current[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		probability = 0.06*probability + 0.94*evidence
	}

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.995 {
		return 0.995
	}
	return probability
}

func candidateUpdateBelief(b candidateBelief,
	amt lnwire.MilliSatoshi, passed bool) candidateBelief {

	if passed {
		if b.upperBad > 0 && amt >= b.upperBad {
			b.upperBad = 0
			b.conf /= 2
		}
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
	} else {
		if b.lowerOK > 0 && amt <= b.lowerOK {
			b.lowerOK = 0
			b.conf /= 2
		}
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
	}

	if b.conf < 16 {
		b.conf++
	}
	return b
}

func (r *candidateRouter) learn(key candidateEdgeKey,
	currentAmt, sharedAmt lnwire.MilliSatoshi, passed bool) {

	r.current[key] = candidateUpdateBelief(
		r.current[key], currentAmt, passed,
	)
	r.shared[key] = candidateUpdateBelief(
		r.shared[key], sharedAmt, passed,
	)

	candidateSharedState.Lock()
	candidateSharedState.beliefs[key] = candidateUpdateBelief(
		candidateSharedState.beliefs[key], sharedAmt, passed,
	)
	candidateSharedState.Unlock()
}

func (r *candidateRouter) hardTotal(edge *candidateEdge) lnwire.MilliSatoshi {
	limit := edge.capacity

	if edge.key.from == r.source {
		local := r.localBalances[edge.key.chanID]
		if local < limit {
			limit = local
		}
	}

	belief, ok := r.current[edge.key]
	if !ok || belief.upperBad == 0 {
		return limit
	}

	var retryLimit lnwire.MilliSatoshi
	if belief.lowerOK > 0 && belief.upperBad > belief.lowerOK {
		retryLimit = belief.lowerOK +
			(belief.upperBad-belief.lowerOK)*42/100
	} else {
		retryLimit = belief.upperBad * 60 / 100
	}

	if retryLimit < limit {
		limit = retryLimit
	}
	return limit
}

func candidateRecommendedFromBelief(b candidateBelief,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	var result lnwire.MilliSatoshi

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		result = b.lowerOK + (b.upperBad-b.lowerOK)*30/100

	case b.upperBad > 0:
		result = b.upperBad * 55 / 100

	case b.lowerOK > 0:
		result = capacity * 88 / 100
		if b.lowerOK > result {
			result = b.lowerOK
		}

	default:
		result = capacity * 78 / 100
	}

	capLimit := capacity * 98 / 100
	if result > capLimit {
		result = capLimit
	}
	return result
}

func (r *candidateRouter) recommendedTotal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	hard := r.hardTotal(edge)
	if edge.key.from == r.source {
		return hard
	}

	var result lnwire.MilliSatoshi
	if belief, ok := r.current[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else if belief, ok := r.shared[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else {
		result = edge.capacity * 78 / 100
	}

	if result > hard {
		result = hard
	}
	return result
}

type candidateQueueItem struct {
	node     route.Vertex
	cost     float64
	arriving lnwire.MilliSatoshi
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64,
	riskScale float64) ([]*candidateEdge, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	dist := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	pq := &candidateQueue{}
	heap.Push(pq, &candidateQueueItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateQueueItem)
		best, ok := dist[item.node]
		if !ok || item.cost > best {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				!edge.usable(item.arriving, true) {

				continue
			}

			limit := r.hardTotal(edge)
			total := item.arriving + r.reserved[edge.key]
			if total > limit || limit <= 0 {
				continue
			}

			probability := r.edgeProbability(edge, total)
			headroomCost := 180_000 *
				float64(total) / float64(limit)
			edgeCost := -math.Log(probability)*riskScale +
				headroomCost + 3_000 +
				r.edgePenalty[edge.key] + diversity[edge.key]

			sending := item.arriving
			if edge.key.from != r.source {
				fee := edge.fee(item.arriving)
				sending += fee
				edgeCost += float64(fee)
			}

			newCost := item.cost + edgeCost
			oldCost, exists := dist[edge.key.from]
			if exists && newCost >= oldCost {
				continue
			}

			dist[edge.key.from] = newCost
			next[edge.key.from] = edge
			heap.Push(pq, &candidateQueueItem{
				node:     edge.key.from,
				cost:     newCost,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("routing cycle")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	return path, nil
}

func candidateSamePath(a, b []*candidateEdge) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].key != b[i].key {
			return false
		}
	}
	return true
}

func candidatePathAmounts(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	amounts := make([]lnwire.MilliSatoshi, len(path))
	if len(path) == 0 {
		return amounts
	}

	amounts[len(path)-1] = finalAmt
	for i := len(path) - 2; i >= 0; i-- {
		next := path[i+1]
		amounts[i] = amounts[i+1] + next.fee(amounts[i+1])
	}
	return amounts
}

func (r *candidateRouter) pathWithin(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe, checkMin bool) bool {

	if finalAmt <= 0 || len(path) == 0 {
		return false
	}

	amounts := candidatePathAmounts(path, finalAmt)
	for i, edge := range path {
		if !edge.usable(amounts[i], checkMin) {
			return false
		}

		limit := r.hardTotal(edge)
		if safe {
			limit = r.recommendedTotal(edge)
		}

		total := amounts[i] + r.reserved[edge.key] +
			planned[edge.key]
		if total > limit {
			return false
		}
	}

	return true
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	want lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe bool) lnwire.MilliSatoshi {

	if want <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := want

	for low < high {
		mid := low + (high-low+1)/2
		if r.pathWithin(path, mid, planned, safe, false) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	if low == 0 ||
		!r.pathWithin(path, low, planned, safe, true) {

		return 0
	}
	return low
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	amounts := candidatePathAmounts(path, amt)
	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = candidateFinalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)
		if i+1 < len(path) {
			forwardAmt = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateAddPlanned(path []*candidateEdge,
	amt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		planned[edge.key] += amounts[i]
	}
}

func candidateClonePlanned(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

type candidateAllocation struct {
	routes    []*route.Route
	planned   map[candidateEdgeKey]lnwire.MilliSatoshi
	remaining lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
	hops      int
	rank      float64
}

func (r *candidateRouter) allocationQuality(
	state *candidateAllocation) float64 {

	quality := -float64(state.fee)/8_000_000 -
		0.025*float64(state.hops) -
		0.10*float64(len(state.routes))

	for key, amount := range state.planned {
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		total := amount + r.reserved[key]
		quality += math.Log(r.edgeProbability(edge, total))
		quality -= r.edgePenalty[key] / 1_500_000
	}

	return quality
}

func (r *candidateRouter) allocationRank(state *candidateAllocation,
	original lnwire.MilliSatoshi) float64 {

	coverage := float64(original-state.remaining) / float64(original)
	return 24*coverage + 0.60*r.allocationQuality(state)
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amount lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amount <= 0 {
		return amounts
	}
	for _, existing := range amounts {
		if existing == amount {
			return amounts
		}
	}
	return append(amounts, amount)
}

func (r *candidateRouter) allocatePlan(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int,
	safe bool) ([]*route.Route, bool) {

	initial := &candidateAllocation{
		planned:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		remaining: amt,
	}
	beam := []*candidateAllocation{initial}

	var best *candidateAllocation
	bestQuality := math.Inf(-1)

	for depth := 0; depth < parts && len(beam) > 0; depth++ {
		var next []*candidateAllocation

		for _, state := range beam {
			slots := parts - len(state.routes)
			if slots <= 0 {
				continue
			}

			fair := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			for _, path := range paths {
				maxAmount := r.maxPathAmount(
					path, state.remaining,
					state.planned, safe,
				)
				if maxAmount == 0 {
					continue
				}

				var choices []lnwire.MilliSatoshi
				choices = candidateAppendAmount(choices, maxAmount)

				fairAmount := fair
				if fairAmount > maxAmount {
					fairAmount = maxAmount
				}
				choices = candidateAppendAmount(choices, fairAmount)
				choices = candidateAppendAmount(
					choices, maxAmount*3/4,
				)
				choices = candidateAppendAmount(
					choices, maxAmount/2,
				)

				if maxAmount >= state.remaining {
					choices = candidateAppendAmount(
						choices, state.remaining,
					)
				}

				for _, amount := range choices {
					if amount > state.remaining ||
						!r.pathWithin(
							path, amount, state.planned,
							safe, true,
						) {

						continue
					}

					rt, err := r.buildRoute(path, amount)
					if err != nil {
						continue
					}

					planned := candidateClonePlanned(
						state.planned,
					)
					candidateAddPlanned(path, amount, planned)

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, rt)

					nextState := &candidateAllocation{
						routes:    routes,
						planned:   planned,
						remaining: state.remaining - amount,
						fee: state.fee +
							(rt.TotalAmount - amount),
						hops: state.hops + len(path),
					}

					if nextState.remaining == 0 {
						quality := r.allocationQuality(
							nextState,
						)
						if quality > bestQuality {
							best = nextState
							bestQuality = quality
						}
						continue
					}

					nextState.rank = r.allocationRank(
						nextState, amt,
					)
					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].rank > next[j].rank
		})
		if len(next) > 48 {
			next = next[:48]
		}
		beam = next
	}

	if best == nil {
		return nil, false
	}
	return best.routes, true
}

func candidateAppendProbe(probes []lnwire.MilliSatoshi,
	probe lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if probe <= 0 {
		return probes
	}
	for _, existing := range probes {
		if existing == probe {
			return probes
		}
	}
	return append(probes, probe)
}

func (r *candidateRouter) discoverPaths(
	amt lnwire.MilliSatoshi, parts int) [][]*candidateEdge {

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var probes []lnwire.MilliSatoshi
	probes = candidateAppendProbe(probes, amt)
	probes = candidateAppendProbe(probes, base)
	probes = candidateAppendProbe(probes, base*3/4)
	probes = candidateAppendProbe(probes, base/2)
	probes = candidateAppendProbe(probes, base/3)
	probes = candidateAppendProbe(probes, base/4)
	probes = candidateAppendProbe(probes, base/8)
	probes = candidateAppendProbe(probes, base/16)
	probes = candidateAppendProbe(probes, base/32)

	var paths [][]*candidateEdge

	for _, probe := range probes {
		diversity := make(map[candidateEdgeKey]float64)
		added := 0

		for round := 0; round < 12 && added < 7; round++ {
			riskScale := 850_000.0
			switch round % 3 {
			case 0:
				riskScale = 1_200_000
			case 1:
				riskScale = 500_000
			}

			path, err := r.findPath(
				probe, diversity, riskScale,
			)
			if err != nil {
				break
			}

			duplicate := false
			for _, existing := range paths {
				if candidateSamePath(existing, path) {
					duplicate = true
					break
				}
			}
			if !duplicate {
				paths = append(paths, path)
				added++
			}

			for _, edge := range path {
				diversity[edge.key] += 2_200_000
			}
		}
	}

	return paths
}

func (r *candidateRouter) fallbackScore(path []*candidateEdge,
	amt, paymentAmt lnwire.MilliSatoshi) float64 {

	amounts := candidatePathAmounts(path, amt)
	logProbability := 0.0
	penalty := 0.0

	for i, edge := range path {
		total := amounts[i] + r.reserved[edge.key]
		logProbability += math.Log(r.edgeProbability(edge, total))
		penalty += r.edgePenalty[edge.key] / 1_500_000
	}

	coverage := float64(amt) / float64(paymentAmt)
	fee := amounts[0] - amt

	return 4.2*math.Log(coverage) + logProbability - penalty -
		float64(fee)/8_000_000 - 0.03*float64(len(path))
}

func (r *candidateRouter) bestFallback(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int) *route.Route {

	planned := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	fair := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	bestScore := math.Inf(-1)
	var best *route.Route

	for _, path := range paths {
		hardMax := r.maxPathAmount(path, amt, planned, false)
		safeMax := r.maxPathAmount(path, amt, planned, true)

		var choices []lnwire.MilliSatoshi
		choices = candidateAppendAmount(choices, safeMax)
		choices = candidateAppendAmount(choices, hardMax)

		fairAmount := fair
		if fairAmount > hardMax {
			fairAmount = hardMax
		}
		choices = candidateAppendAmount(choices, fairAmount)
		choices = candidateAppendAmount(choices, hardMax*3/4)
		choices = candidateAppendAmount(choices, hardMax/2)

		for _, amount := range choices {
			if amount <= 0 ||
				!r.pathWithin(
					path, amount, planned, false, true,
				) {

				continue
			}

			score := r.fallbackScore(path, amount, amt)
			if score <= bestScore {
				continue
			}

			rt, err := r.buildRoute(path, amount)
			if err != nil {
				continue
			}

			best = rt
			bestScore = score
		}
	}

	return best
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts int) ([]*route.Route, error) {

	if parts < 1 {
		return nil, errors.New("maximum parts reached")
	}

	paths := r.discoverPaths(amt, parts)
	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}

	if plan, ok := r.allocatePlan(paths, amt, parts, true); ok {
		return plan, nil
	}
	if plan, ok := r.allocatePlan(paths, amt, parts, false); ok {
		return plan, nil
	}

	fallback := r.bestFallback(paths, amt, parts)
	if fallback != nil {
		return []*route.Route{fallback}, nil
	}

	return nil, errors.New("no route set can carry payment")
}

func candidateDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) takeRoute(rt *route.Route) *route.Route {
	r.attempts++
	return rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}

	if len(r.plan) > 0 {
		next := r.plan[0]
		if candidateDelivered(next) <= amt {
			r.plan = r.plan[1:]
			return r.takeRoute(next), nil
		}
		r.plan = nil
	}

	if r.attempts >= candidateMaxAttempts {
		return nil, errors.New("routing attempts exhausted")
	}

	partsLeft := int(maxParts - inFlightHtlcs)
	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}
	if len(plan) == 0 {
		return nil, errors.New("empty route plan")
	}

	r.plan = plan[1:]
	return r.takeRoute(plan[0]), nil
}

func candidateRouteEdge(rt *route.Route,
	index int) candidateEdgeKey {

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) learnRoutePassed(rt *route.Route,
	end int, reserve bool) {

	if end > len(rt.Hops) {
		end = len(rt.Hops)
	}

	for i := 0; i < end; i++ {
		key := candidateRouteEdge(rt, i)
		amt := candidateRouteAmount(rt, i)
		total := amt + r.reserved[key]
		r.learn(key, total, amt, true)
	}

	if reserve {
		for i := 0; i < end; i++ {
			key := candidateRouteEdge(rt, i)
			r.reserved[key] += candidateRouteAmount(rt, i)
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.learnRoutePassed(rt, len(rt.Hops), true)
		return nil
	}

	r.plan = nil

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)
	if failIndex > 0 {
		r.learnRoutePassed(rt, failIndex, false)
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key := candidateRouteEdge(rt, i)
			r.edgePenalty[key] += 550_000
		}
		return nil
	}

	key := candidateRouteEdge(rt, failIndex)
	amt := candidateRouteAmount(rt, failIndex)
	total := amt + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learn(key, total, amt, false)
		r.edgePenalty[key] += 450_000

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[key] = true

	default:
		r.edgePenalty[key] += 1_200_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateMaxAttempts    = 72
	candidateMaxLabels      = 8
	candidateMaxPaths       = 48
	candidateBeamWidth      = 96
)

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi,
	checkMin bool) bool {

	if amt <= 0 || amt > e.capacity {
		return false
	}
	if checkMin && amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     uint8
}

var candidateSharedState = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	shared  map[candidateEdgeKey]candidateBelief
	current map[candidateEdgeKey]candidateBelief

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	edgePenalty map[candidateEdgeKey]float64
	policyBad   map[candidateEdgeKey]bool

	plan     []*route.Route
	attempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		shared:        make(map[candidateEdgeKey]candidateBelief),
		current:       make(map[candidateEdgeKey]candidateBelief),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		policyBad:     make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateSharedState.Lock()
	for key, edge := range r.edges {
		belief, ok := candidateSharedState.beliefs[key]
		if !ok {
			continue
		}
		if belief.lowerOK > edge.capacity {
			belief.lowerOK = edge.capacity
		}
		if belief.upperBad > edge.capacity {
			belief.upperBad = edge.capacity
		}
		r.shared[key] = belief
	}
	candidateSharedState.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-ratio/0.025)
	highMode := 0.5 / (1 + math.Exp((ratio-0.93)/0.04))
	probability := lowMode + highMode

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.985 {
		return 0.985
	}
	return probability
}

func candidateEvidenceProbability(b candidateBelief,
	amt, capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.005
	}

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		position := float64(amt-b.lowerOK) /
			float64(b.upperBad-b.lowerOK)
		probability := 0.99 - 0.98*position
		if probability < 0.01 {
			return 0.01
		}
		if probability > 0.99 {
			return 0.99
		}
		return probability

	case b.upperBad > 0:
		ratio := float64(amt) / float64(b.upperBad)
		probability := 0.01 + 0.91*math.Exp(-ratio/0.22)
		if probability > 0.99 {
			return 0.99
		}
		return probability

	case b.lowerOK > 0:
		if capacity <= b.lowerOK {
			return 0.985
		}
		distance := float64(amt-b.lowerOK) / float64(capacity)
		probability := 0.61 + 0.37*math.Exp(-distance/0.20)
		if probability > 0.99 {
			return 0.99
		}
		return probability
	}

	return candidatePrior(amt, capacity)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	probability := candidatePrior(total, edge.capacity)

	if belief, ok := r.shared[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 4.0)
		if weight > 0.70 {
			weight = 0.70
		}
		probability = probability*(1-weight) + evidence*weight
	}

	if belief, ok := r.current[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 0.45)
		if weight > 0.97 {
			weight = 0.97
		}
		probability = probability*(1-weight) + evidence*weight
	}

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.995 {
		return 0.995
	}
	return probability
}

func candidateUpdateBelief(b candidateBelief,
	amt lnwire.MilliSatoshi, passed bool) candidateBelief {

	if amt <= 0 {
		return b
	}

	if passed {
		if b.upperBad > 0 && amt >= b.upperBad {
			b.upperBad = 0
			b.conf /= 2
		}
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
	} else {
		if b.lowerOK > 0 && amt <= b.lowerOK {
			b.lowerOK = 0
			b.conf /= 2
		}
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
	}

	if b.conf < 16 {
		b.conf++
	}
	return b
}

func (r *candidateRouter) learn(key candidateEdgeKey,
	currentAmt, sharedAmt lnwire.MilliSatoshi, passed bool) {

	r.current[key] = candidateUpdateBelief(
		r.current[key], currentAmt, passed,
	)

	if passed {
		r.edgePenalty[key] *= 0.35
	}

	// A failure while another atomic shard is held only establishes a
	// bound on their combined amount. Do not turn that contingent bound
	// into a cross-payment standalone failure.
	if !passed && currentAmt != sharedAmt {
		return
	}

	candidateSharedState.Lock()
	updated := candidateUpdateBelief(
		candidateSharedState.beliefs[key], sharedAmt, passed,
	)
	candidateSharedState.beliefs[key] = updated
	candidateSharedState.Unlock()

	r.shared[key] = updated
}

func (r *candidateRouter) addPenalty(key candidateEdgeKey, amount float64) {
	r.edgePenalty[key] += amount
	if r.edgePenalty[key] > 1_500_000 {
		r.edgePenalty[key] = 1_500_000
	}
}

func (r *candidateRouter) hardTotal(edge *candidateEdge) lnwire.MilliSatoshi {
	limit := edge.capacity

	if edge.key.from == r.source {
		local := r.localBalances[edge.key.chanID]
		if local < limit {
			limit = local
		}
	}

	belief, ok := r.current[edge.key]
	if !ok || belief.upperBad == 0 {
		return limit
	}

	var retryLimit lnwire.MilliSatoshi
	if belief.lowerOK > 0 && belief.upperBad > belief.lowerOK {
		retryLimit = belief.lowerOK +
			(belief.upperBad-belief.lowerOK)*55/100
	} else {
		retryLimit = belief.upperBad * 70 / 100
	}

	if retryLimit < limit {
		limit = retryLimit
	}
	return limit
}

func candidateRecommendedFromBelief(b candidateBelief,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	var result lnwire.MilliSatoshi

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		result = b.lowerOK + (b.upperBad-b.lowerOK)*30/100

	case b.upperBad > 0:
		result = b.upperBad * 28 / 100

	case b.lowerOK > 0:
		result = capacity * 90 / 100
		if b.lowerOK > result {
			result = b.lowerOK
		}

	default:
		result = capacity * 72 / 100
	}

	capLimit := capacity * 98 / 100
	if result > capLimit {
		result = capLimit
	}
	return result
}

func (r *candidateRouter) recommendedTotal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	hard := r.hardTotal(edge)
	if edge.key.from == r.source {
		return hard
	}

	var result lnwire.MilliSatoshi
	if belief, ok := r.current[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else if belief, ok := r.shared[edge.key]; ok {
		result = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else {
		result = edge.capacity * 72 / 100
	}

	if result > hard {
		result = hard
	}
	return result
}

type candidatePathLabel struct {
	node     route.Vertex
	cost     float64
	arriving lnwire.MilliSatoshi
	path     []*candidateEdge
	alive    bool
}

type candidateQueue []*candidatePathLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if q[i].cost == q[j].cost {
		return q[i].arriving < q[j].arriving
	}
	return q[i].cost < q[j].cost
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidatePathLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func candidateDominates(a, b *candidatePathLabel) bool {
	return a.cost <= b.cost && a.arriving <= b.arriving
}

func candidatePathHasVertex(path []*candidateEdge,
	vertex route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == vertex || edge.key.to == vertex {
			return true
		}
	}
	return false
}

func candidateInsertLabel(
	labels map[route.Vertex][]*candidatePathLabel,
	pq *candidateQueue, label *candidatePathLabel) {

	existing := labels[label.node]
	for _, old := range existing {
		if old.alive && candidateDominates(old, label) {
			label.alive = false
			return
		}
	}

	kept := make([]*candidatePathLabel, 0, len(existing)+1)
	for _, old := range existing {
		if !old.alive {
			continue
		}
		if candidateDominates(label, old) {
			old.alive = false
			continue
		}
		kept = append(kept, old)
	}

	label.alive = true
	kept = append(kept, label)
	sort.Slice(kept, func(i, j int) bool {
		if kept[i].cost == kept[j].cost {
			return kept[i].arriving < kept[j].arriving
		}
		return kept[i].cost < kept[j].cost
	})

	if len(kept) > candidateMaxLabels {
		for _, dropped := range kept[candidateMaxLabels:] {
			dropped.alive = false
		}
		kept = kept[:candidateMaxLabels]
	}
	labels[label.node] = kept

	if label.alive {
		heap.Push(pq, label)
	}
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64,
	riskScale float64) ([]*candidateEdge, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	labels := make(map[route.Vertex][]*candidatePathLabel)
	pq := &candidateQueue{}
	initial := &candidatePathLabel{
		node:     r.spec.Target,
		arriving: amt,
		alive:    true,
	}
	labels[r.spec.Target] = []*candidatePathLabel{initial}
	heap.Push(pq, initial)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidatePathLabel)
		if !item.alive {
			continue
		}
		if item.node == r.source {
			return item.path, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				!edge.usable(item.arriving, true) {

				continue
			}
			if edge.key.from == item.node ||
				candidatePathHasVertex(item.path, edge.key.from) {

				continue
			}

			limit := r.hardTotal(edge)
			total := item.arriving + r.reserved[edge.key]
			if limit <= 0 || total > limit {
				continue
			}

			probability := r.edgeProbability(edge, total)
			utilization := float64(total) / float64(limit)
			headroomCost := 125_000 * utilization *
				utilization * utilization

			edgeCost := -math.Log(probability)*riskScale +
				headroomCost + 42_000 +
				r.edgePenalty[edge.key] + diversity[edge.key]

			sending := item.arriving
			if edge.key.from != r.source {
				fee := edge.fee(item.arriving)
				sending += fee
				edgeCost += float64(fee)
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			candidateInsertLabel(labels, pq, &candidatePathLabel{
				node:     edge.key.from,
				cost:     item.cost + edgeCost,
				arriving: sending,
				path:     path,
			})
		}
	}

	return nil, errors.New("no route found")
}

func candidateSamePath(a, b []*candidateEdge) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].key != b[i].key {
			return false
		}
	}
	return true
}

func candidatePathAmounts(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	amounts := make([]lnwire.MilliSatoshi, len(path))
	if len(path) == 0 {
		return amounts
	}

	amounts[len(path)-1] = finalAmt
	for i := len(path) - 2; i >= 0; i-- {
		amounts[i] = amounts[i+1] +
			path[i+1].fee(amounts[i+1])
	}
	return amounts
}

func (r *candidateRouter) pathWithin(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe, checkMin bool) bool {

	if finalAmt <= 0 || len(path) == 0 {
		return false
	}

	amounts := candidatePathAmounts(path, finalAmt)
	for i, edge := range path {
		if !edge.usable(amounts[i], checkMin) {
			return false
		}

		limit := r.hardTotal(edge)
		if safe {
			limit = r.recommendedTotal(edge)
		}

		total := amounts[i] + r.reserved[edge.key] +
			planned[edge.key]
		if limit <= 0 || total > limit {
			return false
		}
	}

	return true
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	want lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe bool) lnwire.MilliSatoshi {

	if want <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := want

	for low < high {
		mid := low + (high-low+1)/2
		if r.pathWithin(path, mid, planned, safe, false) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	if low == 0 || !r.pathWithin(path, low, planned, safe, true) {
		return 0
	}
	return low
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	amounts := candidatePathAmounts(path, amt)
	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = candidateFinalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)
		if i+1 < len(path) {
			forwardAmt = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateAddPlanned(path []*candidateEdge,
	amt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		planned[edge.key] += amounts[i]
	}
}

func candidateClonePlanned(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

type candidateAllocation struct {
	routes    []*route.Route
	planned   map[candidateEdgeKey]lnwire.MilliSatoshi
	remaining lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
	hops      int
	rank      float64
}

func (r *candidateRouter) allocationQuality(
	state *candidateAllocation) float64 {

	quality := -float64(state.fee)/12_000_000 -
		0.025*float64(state.hops) -
		0.08*float64(len(state.routes))

	for key, amount := range state.planned {
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		total := amount + r.reserved[key]
		quality += math.Log(r.edgeProbability(edge, total))
		quality -= r.edgePenalty[key] / 900_000
	}

	return quality
}

func (r *candidateRouter) allocationRank(state *candidateAllocation,
	original lnwire.MilliSatoshi) float64 {

	coverage := float64(original-state.remaining) / float64(original)
	return 60*coverage + 0.15*r.allocationQuality(state)
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amount lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amount <= 0 {
		return amounts
	}
	for _, existing := range amounts {
		if existing == amount {
			return amounts
		}
	}
	return append(amounts, amount)
}

func (r *candidateRouter) routeReliability(rt *route.Route) float64 {
	result := 0.0
	for i := range rt.Hops {
		key := candidateRouteEdge(rt, i)
		edge := r.edges[key]
		if edge == nil {
			continue
		}
		total := candidateRouteAmount(rt, i) + r.reserved[key]
		result += math.Log(r.edgeProbability(edge, total))
		result -= r.edgePenalty[key] / 900_000
	}
	return result
}

func (r *candidateRouter) orderPlan(routes []*route.Route) {
	sort.SliceStable(routes, func(i, j int) bool {
		left := r.routeReliability(routes[i])
		right := r.routeReliability(routes[j])
		if left == right {
			return candidateDelivered(routes[i]) >
				candidateDelivered(routes[j])
		}
		return left < right
	})
}

func (r *candidateRouter) allocatePlan(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int,
	safe bool) ([]*route.Route, bool) {

	initial := &candidateAllocation{
		planned:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		remaining: amt,
	}
	beam := []*candidateAllocation{initial}

	var best *candidateAllocation
	bestQuality := math.Inf(-1)

	for depth := 0; depth < parts && len(beam) > 0; depth++ {
		var next []*candidateAllocation

		for _, state := range beam {
			slots := parts - len(state.routes)
			if slots <= 0 || state.remaining <= 0 {
				continue
			}

			fair := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			for _, path := range paths {
				maxAmount := r.maxPathAmount(
					path, state.remaining,
					state.planned, safe,
				)
				if maxAmount == 0 {
					continue
				}

				var choices []lnwire.MilliSatoshi
				if maxAmount >= state.remaining {
					choices = candidateAppendAmount(
						choices, state.remaining,
					)
				}
				choices = candidateAppendAmount(choices, maxAmount)

				fairAmount := fair
				if fairAmount > maxAmount {
					fairAmount = maxAmount
				}
				choices = candidateAppendAmount(choices, fairAmount)
				choices = candidateAppendAmount(
					choices, maxAmount*3/4,
				)
				choices = candidateAppendAmount(
					choices, maxAmount/2,
				)
				choices = candidateAppendAmount(
					choices, maxAmount/3,
				)

				for _, amount := range choices {
					if amount > state.remaining ||
						!r.pathWithin(
							path, amount, state.planned,
							safe, true,
						) {

						continue
					}

					rt, err := r.buildRoute(path, amount)
					if err != nil {
						continue
					}

					planned := candidateClonePlanned(
						state.planned,
					)
					candidateAddPlanned(path, amount, planned)

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, rt)

					nextState := &candidateAllocation{
						routes:    routes,
						planned:   planned,
						remaining: state.remaining - amount,
						fee: state.fee +
							(rt.TotalAmount - amount),
						hops: state.hops + len(path),
					}

					if nextState.remaining == 0 {
						quality := r.allocationQuality(
							nextState,
						)
						if quality > bestQuality {
							best = nextState
							bestQuality = quality
						}
						continue
					}

					if len(nextState.routes) >= parts {
						continue
					}

					nextState.rank = r.allocationRank(
						nextState, amt,
					)
					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].rank > next[j].rank
		})
		if len(next) > candidateBeamWidth {
			next = next[:candidateBeamWidth]
		}
		beam = next
	}

	if best == nil {
		return nil, false
	}

	r.orderPlan(best.routes)
	return best.routes, true
}

func candidateAppendProbe(probes []lnwire.MilliSatoshi,
	probe lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if probe <= 0 {
		return probes
	}
	for _, existing := range probes {
		if existing == probe {
			return probes
		}
	}
	return append(probes, probe)
}

func (r *candidateRouter) discoverPaths(
	amt lnwire.MilliSatoshi, parts int) [][]*candidateEdge {

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var probes []lnwire.MilliSatoshi
	probes = candidateAppendProbe(probes, amt)
	probes = candidateAppendProbe(probes, base)
	probes = candidateAppendProbe(probes, base*3/4)
	probes = candidateAppendProbe(probes, base/2)
	probes = candidateAppendProbe(probes, base/4)
	probes = candidateAppendProbe(probes, base/8)
	probes = candidateAppendProbe(probes, base/16)
	probes = candidateAppendProbe(probes, base/64)

	riskScales := []float64{
		1_350_000,
		800_000,
		420_000,
		220_000,
	}

	var paths [][]*candidateEdge
	for _, probe := range probes {
		diversity := make(map[candidateEdgeKey]float64)

		for round := 0; round < 8; round++ {
			path, err := r.findPath(
				probe, diversity,
				riskScales[round%len(riskScales)],
			)
			if err != nil {
				break
			}

			duplicate := false
			for _, existing := range paths {
				if candidateSamePath(existing, path) {
					duplicate = true
					break
				}
			}
			if !duplicate {
				paths = append(paths, path)
				if len(paths) >= candidateMaxPaths {
					return paths
				}
			}

			for i, edge := range path {
				diversity[edge.key] += 300_000
				if i == 0 || i == len(path)-1 {
					diversity[edge.key] += 220_000
				}
			}
		}
	}

	return paths
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts int) ([]*route.Route, error) {

	if parts < 1 {
		return nil, errors.New("maximum parts reached")
	}

	paths := r.discoverPaths(amt, parts)
	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}

	if plan, ok := r.allocatePlan(paths, amt, parts, true); ok {
		return plan, nil
	}
	if plan, ok := r.allocatePlan(paths, amt, parts, false); ok {
		return plan, nil
	}

	return nil, errors.New("no route set can carry payment")
}

func candidateDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) takeRoute(rt *route.Route) *route.Route {
	r.attempts++
	return rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}
	if r.attempts >= candidateMaxAttempts {
		return nil, errors.New("routing attempts exhausted")
	}

	if len(r.plan) > 0 {
		next := r.plan[0]
		if candidateDelivered(next) <= amt {
			r.plan = r.plan[1:]
			return r.takeRoute(next), nil
		}
		r.plan = nil
	}

	partsLeft := int(maxParts - inFlightHtlcs)
	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}
	if len(plan) == 0 {
		return nil, errors.New("empty route plan")
	}

	r.plan = plan[1:]
	return r.takeRoute(plan[0]), nil
}

func candidateRouteEdge(rt *route.Route,
	index int) candidateEdgeKey {

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) learnRoutePassed(rt *route.Route,
	end int, reserve bool) {

	if end > len(rt.Hops) {
		end = len(rt.Hops)
	}

	for i := 0; i < end; i++ {
		key := candidateRouteEdge(rt, i)
		amt := candidateRouteAmount(rt, i)
		total := amt + r.reserved[key]
		r.learn(key, total, amt, true)
	}

	if reserve {
		for i := 0; i < end; i++ {
			key := candidateRouteEdge(rt, i)
			r.reserved[key] += candidateRouteAmount(rt, i)
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.learnRoutePassed(rt, len(rt.Hops), true)
		return nil
	}

	r.plan = nil

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)
	if failIndex > 0 {
		r.learnRoutePassed(rt, failIndex, false)
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			r.addPenalty(candidateRouteEdge(rt, i), 260_000)
		}
		return nil
	}

	key := candidateRouteEdge(rt, failIndex)
	amt := candidateRouteAmount(rt, failIndex)
	total := amt + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learn(key, total, amt, false)
		r.addPenalty(key, 170_000)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[key] = true

	default:
		r.addPenalty(key, 750_000)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) key() edgeKey {
	return edgeKey{chanID: e.chanID, from: e.from}
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	conf     float64
}

var candidateMemory = struct {
	sync.Mutex
	refs    map[uintptr]routing.SimNetworkView
	beliefs map[uintptr]map[edgeKey]liquidityBelief
}{
	refs:    make(map[uintptr]routing.SimNetworkView),
	beliefs: make(map[uintptr]map[edgeKey]liquidityBelief),
}

func viewScope(view routing.SimNetworkView) uintptr {
	value := reflect.ValueOf(view)
	switch value.Kind() {
	case reflect.Chan, reflect.Func, reflect.Map, reflect.Ptr,
		reflect.Slice, reflect.UnsafePointer:

		if value.IsNil() {
			return 0
		}
		return value.Pointer()
	default:
		return 0
	}
}

func evolveBelief(b liquidityBelief, capacity,
	observed lnwire.MilliSatoshi, passed bool) liquidityBelief {

	if observed < 0 {
		observed = 0
	}
	if observed > capacity {
		observed = capacity
	}

	priorEstimate := capacity * 3 / 4
	if b.conf == 0 {
		b.estimate = priorEstimate
	}

	if passed {
		if observed > b.lowerOK {
			b.lowerOK = observed
		}
		if b.upperBad != 0 && observed >= b.upperBad {
			b.upperBad = 0
		}

		target := observed + (capacity-observed)*4/5
		b.estimate = (b.estimate + 3*target) / 4
	} else {
		if b.upperBad == 0 || observed < b.upperBad {
			b.upperBad = observed
		}
		if b.lowerOK >= observed {
			b.lowerOK = observed / 4
		}

		target := observed / 4
		lowMode := capacity / 12
		if target > lowMode {
			target = lowMode
		}
		b.estimate = (b.estimate + 4*target) / 5
	}

	if b.estimate < b.lowerOK {
		b.estimate = b.lowerOK
	}
	if b.upperBad != 0 && b.estimate >= b.upperBad {
		b.estimate = b.upperBad * 2 / 3
	}
	if b.estimate > capacity {
		b.estimate = capacity
	}

	b.conf++
	if b.conf > 8 {
		b.conf = 8
	}

	return b
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec
	scope  uintptr

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	localFailures map[edgeKey]lnwire.MilliSatoshi
	badPolicy     map[edgeKey]bool
	reserved      map[edgeKey]lnwire.MilliSatoshi
	penalty       map[edgeKey]float64

	plan []*route.Route
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	scope := viewScope(view)
	r := &candidateRouter{
		source:        source,
		spec:          spec,
		scope:         scope,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[edgeKey]liquidityBelief),
		localFailures: make(map[edgeKey]lnwire.MilliSatoshi),
		badPolicy:     make(map[edgeKey]bool),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		penalty:       make(map[edgeKey]float64),
	}

	candidateMemory.Lock()
	if scope != 0 {
		candidateMemory.refs[scope] = view
	}
	for key, belief := range candidateMemory.beliefs[scope] {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func (r *candidateRouter) observe(edge edgeKey,
	capacity, amount lnwire.MilliSatoshi, passed bool) {

	r.beliefs[edge] = evolveBelief(
		r.beliefs[edge], capacity, amount, passed,
	)

	candidateMemory.Lock()
	networkBeliefs := candidateMemory.beliefs[r.scope]
	if networkBeliefs == nil {
		networkBeliefs = make(map[edgeKey]liquidityBelief)
		candidateMemory.beliefs[r.scope] = networkBeliefs
	}
	networkBeliefs[edge] = evolveBelief(
		networkBeliefs[edge], capacity, amount, passed,
	)
	candidateMemory.Unlock()
}

func bimodalPrior(amount, capacity lnwire.MilliSatoshi) float64 {
	if amount <= 0 {
		return 0.985
	}
	if capacity <= 0 || amount >= capacity {
		return 0.005
	}

	x := float64(amount) / float64(capacity)
	lowMode := math.Exp(-x / 0.035)
	highMode := 1 / (1 + math.Exp((x-0.86)/0.045))
	probability := 0.48*lowMode + 0.50*highMode + 0.005

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.985 {
		return 0.985
	}
	return probability
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	required lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if required <= r.localBalances[edge.chanID] {
			return 0.999
		}
		return 0.001
	}

	prior := bimodalPrior(required, edge.capacity)
	belief, ok := r.beliefs[edge.key()]
	if !ok || belief.conf == 0 {
		return prior
	}

	if belief.lowerOK != 0 && required <= belief.lowerOK {
		return 0.995
	}
	if belief.upperBad != 0 && required >= belief.upperBad {
		return 0.005
	}

	scale := float64(edge.capacity) * 0.06
	if scale < 1 {
		scale = 1
	}
	pointProbability := 1 / (1 + math.Exp(
		(float64(required)-float64(belief.estimate))/scale,
	))
	weight := belief.conf / (belief.conf + 1.5)
	probability := (1-weight)*prior + weight*pointProbability

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.995 {
		return 0.995
	}
	return probability
}

func (r *candidateRouter) estimatedLimit(
	edge *candidateEdge) lnwire.MilliSatoshi {

	if edge.from == r.source {
		limit := r.localBalances[edge.chanID]
		if limit > edge.capacity {
			limit = edge.capacity
		}
		return limit
	}

	belief, ok := r.beliefs[edge.key()]
	if !ok || belief.conf == 0 {
		return edge.capacity * 78 / 100
	}

	limit := belief.estimate
	if limit < belief.lowerOK {
		limit = belief.lowerOK
	}
	if belief.upperBad != 0 && limit >= belief.upperBad {
		limit = belief.upperBad * 2 / 3
	}
	if limit > edge.capacity {
		limit = edge.capacity
	}
	return limit
}

type searchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
}

type searchQueue []*searchItem

func (q searchQueue) Len() int { return len(q) }
func (q searchQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].amount < q[j].amount
	}
	return q[i].score < q[j].score
}
func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}
func (q *searchQueue) Push(value any) {
	*q = append(*q, value.(*searchItem))
}
func (q *searchQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func (r *candidateRouter) locallyAllowed(edge *candidateEdge,
	amount lnwire.MilliSatoshi,
	reserve map[edgeKey]lnwire.MilliSatoshi) bool {

	if !edge.usable(amount) || r.badPolicy[edge.key()] {
		return false
	}

	key := edge.key()
	total := amount + reserve[key]
	if total > edge.capacity {
		return false
	}

	if edge.from == r.source &&
		total > r.localBalances[edge.chanID] {

		return false
	}

	if failed, ok := r.localFailures[key]; ok {
		retryCeiling := failed * 7 / 10
		if total >= retryCeiling {
			return false
		}
	}

	return true
}

func (r *candidateRouter) findPath(amount lnwire.MilliSatoshi,
	reserve map[edgeKey]lnwire.MilliSatoshi,
	diversity map[edgeKey]float64) ([]*candidateEdge, error) {

	if amount <= 0 {
		return nil, errors.New("invalid route amount")
	}

	best := make(map[route.Vertex]float64)
	arrivingAt := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	best[r.spec.Target] = 0
	arrivingAt[r.spec.Target] = amount

	queue := &searchQueue{}
	heap.Push(queue, &searchItem{
		node:   r.spec.Target,
		amount: amount,
	})

	feeDenominator := float64(amount)
	if feeDenominator < 1 {
		feeDenominator = 1
	}

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*searchItem)
		currentBest, ok := best[item.node]
		if !ok || item.score > currentBest+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOver := item.amount
			if !r.locallyAllowed(edge, amountOver, reserve) {
				continue
			}

			key := edge.key()
			required := amountOver + reserve[key]
			probability := r.edgeProbability(edge, required)

			sending := amountOver
			feeCost := 0.0
			if edge.from != r.source {
				fee := edge.fee(amountOver)
				sending += fee
				feeCost = 12 * float64(fee) / feeDenominator
			}

			score := item.score - math.Log(probability) +
				feeCost + 0.012 + r.penalty[key]
			if diversity != nil {
				score += diversity[key]
			}

			previous, exists := best[edge.from]
			if exists && score >= previous {
				continue
			}

			best[edge.from] = score
			arrivingAt[edge.from] = sending
			next[edge.from] = edge
			heap.Push(queue, &searchItem{
				node:   edge.from,
				amount: sending,
				score:  score,
			})
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	var path []*candidateEdge
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("routing cycle")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	return path, nil
}

func pathAmounts(path []*candidateEdge,
	finalAmount lnwire.MilliSatoshi) ([]lnwire.MilliSatoshi, bool) {

	if len(path) == 0 || finalAmount <= 0 {
		return nil, false
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	amounts[len(path)-1] = finalAmount
	for i := len(path) - 2; i >= 0; i-- {
		nextEdge := path[i+1]
		amounts[i] = amounts[i+1] + nextEdge.fee(amounts[i+1])
	}
	return amounts, true
}

func pathMinimum(path []*candidateEdge) lnwire.MilliSatoshi {
	minimum := lnwire.MilliSatoshi(1)
	for _, edge := range path {
		if edge.minHTLC > minimum {
			minimum = edge.minHTLC
		}
	}
	return minimum
}

func (r *candidateRouter) pathFeasible(path []*candidateEdge,
	finalAmount lnwire.MilliSatoshi,
	reserve map[edgeKey]lnwire.MilliSatoshi,
	useEstimate bool) bool {

	amounts, ok := pathAmounts(path, finalAmount)
	if !ok {
		return false
	}

	for i, edge := range path {
		if !r.locallyAllowed(edge, amounts[i], reserve) {
			return false
		}
		if useEstimate {
			total := amounts[i] + reserve[edge.key()]
			if total > r.estimatedLimit(edge) {
				return false
			}
		}
	}
	return true
}

func (r *candidateRouter) pathMaximum(path []*candidateEdge,
	maximum lnwire.MilliSatoshi,
	reserve map[edgeKey]lnwire.MilliSatoshi,
	useEstimate bool) lnwire.MilliSatoshi {

	minimum := pathMinimum(path)
	if maximum < minimum {
		return 0
	}
	if r.pathFeasible(path, maximum, reserve, useEstimate) {
		return maximum
	}
	if !r.pathFeasible(path, minimum, reserve, useEstimate) {
		return 0
	}

	low, high := minimum, maximum
	for low < high {
		middle := low + (high-low+1)/2
		if r.pathFeasible(path, middle, reserve, useEstimate) {
			low = middle
		} else {
			high = middle - 1
		}
	}
	return low
}

func (r *candidateRouter) pathProbability(path []*candidateEdge,
	finalAmount lnwire.MilliSatoshi,
	reserve map[edgeKey]lnwire.MilliSatoshi) float64 {

	amounts, ok := pathAmounts(path, finalAmount)
	if !ok {
		return 0
	}

	logProbability := 0.0
	for i, edge := range path {
		required := amounts[i] + reserve[edge.key()]
		logProbability += math.Log(
			r.edgeProbability(edge, required),
		)
	}
	if logProbability < -700 {
		return 0
	}
	return math.Exp(logProbability)
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	finalAmount lnwire.MilliSatoshi) (*route.Route, error) {

	amounts, ok := pathAmounts(path, finalAmount)
	if !ok {
		return nil, errors.New("empty route")
	}

	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = finalCltvDelta
	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := finalAmount
		outgoingExpiry := uint32(finalCltvDelta)
		if i < len(path)-1 {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func copyReservations(
	source map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	result := make(map[edgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func reservePath(reserve map[edgeKey]lnwire.MilliSatoshi,
	path []*candidateEdge, finalAmount lnwire.MilliSatoshi) {

	amounts, ok := pathAmounts(path, finalAmount)
	if !ok {
		return
	}
	for i, edge := range path {
		reserve[edge.key()] += amounts[i]
	}
}

func pathSignature(path []*candidateEdge) string {
	signature := ""
	for _, edge := range path {
		signature += fmt.Sprintf(
			"%d:%x|", edge.chanID, edge.from[:],
		)
	}
	return signature
}

type plannedPath struct {
	path    []*candidateEdge
	minimum lnwire.MilliSatoshi
}

func (r *candidateRouter) discoverPaths(total lnwire.MilliSatoshi,
	parts int, fullPath []*candidateEdge) []plannedPath {

	wanted := parts * 3
	if wanted < parts+2 {
		wanted = parts + 2
	}
	if wanted > 14 {
		wanted = 14
	}

	diversity := make(map[edgeKey]float64)
	known := make(map[string]bool)
	paths := make([]plannedPath, 0, wanted)

	addPath := func(path []*candidateEdge) bool {
		signature := pathSignature(path)
		if known[signature] {
			for _, edge := range path {
				diversity[edge.key()] += 8
			}
			return false
		}

		if r.pathMaximum(
			path, total, r.reserved, false,
		) < pathMinimum(path) {

			return false
		}

		known[signature] = true
		paths = append(paths, plannedPath{
			path:    path,
			minimum: pathMinimum(path),
		})
		for _, edge := range path {
			diversity[edge.key()] += 6
		}
		return true
	}

	if len(fullPath) != 0 {
		addPath(fullPath)
	}

	baseProbe := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)
	if baseProbe < 1 {
		baseProbe = 1
	}

	for attempt := 0; attempt < wanted*4 && len(paths) < wanted;
		attempt++ {

		probe := baseProbe
		switch attempt % 3 {
		case 1:
			probe = baseProbe / 2
		case 2:
			probe = baseProbe * 2
			if probe > total {
				probe = total
			}
		}
		if probe < 1 {
			probe = 1
		}

		for {
			path, err := r.findPath(
				probe, r.reserved, diversity,
			)
			if err == nil {
				addPath(path)
				break
			}
			if probe <= 1 {
				break
			}
			nextProbe := probe * 2 / 3
			if nextProbe >= probe {
				nextProbe = probe - 1
			}
			if nextProbe < 1 {
				nextProbe = 1
			}
			probe = nextProbe
		}
	}

	return paths
}

func addSaturating(current, add,
	limit lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if current >= limit || add >= limit-current {
		return limit
	}
	return current + add
}

func (r *candidateRouter) buildRouteSet(total lnwire.MilliSatoshi,
	candidates []plannedPath) []*route.Route {

	reserve := copyReservations(r.reserved)
	remaining := total
	routes := make([]*route.Route, 0, len(candidates))

	for index, candidate := range candidates {
		publicMax := r.pathMaximum(
			candidate.path, remaining, reserve, false,
		)
		if publicMax < candidate.minimum {
			return nil
		}

		futureMinimum := lnwire.MilliSatoshi(0)
		futurePublic := lnwire.MilliSatoshi(0)
		weightSum := 0.0

		currentSafe := r.pathMaximum(
			candidate.path, remaining, reserve, true,
		)
		if currentSafe < candidate.minimum {
			currentSafe = publicMax / 3
			if currentSafe < candidate.minimum {
				currentSafe = candidate.minimum
			}
		}
		weightSum += float64(currentSafe)

		for _, future := range candidates[index+1:] {
			futureMinimum = addSaturating(
				futureMinimum, future.minimum, remaining,
			)

			futureMax := r.pathMaximum(
				future.path, remaining, reserve, false,
			)
			futurePublic = addSaturating(
				futurePublic, futureMax, remaining,
			)

			futureSafe := r.pathMaximum(
				future.path, remaining, reserve, true,
			)
			if futureSafe < future.minimum {
				futureSafe = futureMax / 3
				if futureSafe < future.minimum {
					futureSafe = future.minimum
				}
			}
			weightSum += float64(futureSafe)
		}

		lower := candidate.minimum
		if remaining > futurePublic {
			requiredNow := remaining - futurePublic
			if requiredNow > lower {
				lower = requiredNow
			}
		}

		if remaining <= futureMinimum {
			return nil
		}
		upper := remaining - futureMinimum
		if upper > publicMax {
			upper = publicMax
		}
		if lower > upper {
			return nil
		}

		allocation := lower
		if weightSum > 0 {
			proportional := lnwire.MilliSatoshi(
				float64(remaining) *
					float64(currentSafe) / weightSum,
			)
			if proportional > allocation {
				allocation = proportional
			}
		}
		if allocation > upper {
			allocation = upper
		}

		rt, err := r.buildRoute(candidate.path, allocation)
		if err != nil {
			return nil
		}
		routes = append(routes, rt)
		reservePath(reserve, candidate.path, allocation)
		remaining -= allocation
	}

	if remaining != 0 {
		return nil
	}
	return routes
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts int) []*route.Route {

	if parts < 1 {
		return nil
	}

	probe := total
	if parts > 1 {
		probe = (total + lnwire.MilliSatoshi(parts) - 1) /
			lnwire.MilliSatoshi(parts)
	}

	for {
		path, err := r.findPath(probe, r.reserved, nil)
		if err == nil {
			rt, buildErr := r.buildRoute(path, probe)
			if buildErr == nil {
				return []*route.Route{rt}
			}
		}

		if parts == 1 || probe <= 1 {
			return nil
		}

		nextProbe := probe * 2 / 3
		if nextProbe >= probe {
			nextProbe = probe - 1
		}
		if nextProbe < 1 {
			nextProbe = 1
		}
		probe = nextProbe
	}
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts int) []*route.Route {

	if parts < 1 {
		return nil
	}
	if parts > 6 {
		parts = 6
	}

	fullPath, fullErr := r.findPath(total, r.reserved, nil)
	if fullErr == nil {
		probability := r.pathProbability(
			fullPath, total, r.reserved,
		)
		if parts == 1 || probability >= 0.90 ||
			(total <= 2_000_000 && probability >= 0.70) {

			rt, err := r.buildRoute(fullPath, total)
			if err == nil {
				return []*route.Route{rt}
			}
		}
	} else {
		fullPath = nil
	}

	if parts == 1 {
		return nil
	}

	paths := r.discoverPaths(total, parts, fullPath)
	maxParts := parts
	if maxParts > len(paths) {
		maxParts = len(paths)
	}

	for count := maxParts; count >= 2; count-- {
		starts := len(paths)
		if starts > 8 {
			starts = 8
		}

		for start := 0; start < starts; start++ {
			selected := make([]plannedPath, 0, count)
			for offset := 0; offset < len(paths) &&
				len(selected) < count; offset++ {

				index := (start + offset) % len(paths)
				selected = append(selected, paths[index])
			}

			routes := r.buildRouteSet(total, selected)
			if len(routes) != 0 {
				return routes
			}
		}
	}

	return r.fallbackShard(total, parts)
}

func routeFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeDirectedEdges(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	if rt == nil || len(rt.Hops) == 0 {
		return nil, nil
	}

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{chanID: hop.ChannelID, from: from}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) routeStillAllowed(rt *route.Route) bool {
	keys, amounts := routeDirectedEdges(rt)
	for i, key := range keys {
		if r.badPolicy[key] {
			return false
		}

		total := amounts[i] + r.reserved[key]
		if failed, ok := r.localFailures[key]; ok &&
			total >= failed*7/10 {

			return false
		}

		if total > r.localBalances[key.chanID] &&
			key.from == r.source {

			return false
		}
	}
	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment already complete")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("no MPP slots remaining")
	}
	parts := int(maxParts - inFlightHtlcs)

	for {
		for len(r.plan) != 0 {
			rt := r.plan[0]
			r.plan = r.plan[1:]

			finalAmount := routeFinalAmount(rt)
			if finalAmount == 0 || finalAmount > amt {
				r.plan = nil
				break
			}
			if !r.routeStillAllowed(rt) {
				r.plan = nil
				break
			}
			return rt, nil
		}

		r.plan = r.makePlan(amt, parts)
		if len(r.plan) == 0 {
			return nil, errors.New("no route plan found")
		}
	}
}

func (r *candidateRouter) edgeCapacity(key edgeKey) lnwire.MilliSatoshi {
	for _, edges := range r.incomingEdges {
		for _, edge := range edges {
			if edge.key() == key {
				return edge.capacity
			}
		}
	}
	return 0
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeDirectedEdges(rt)
	if len(keys) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i, key := range keys {
			total := amounts[i] + r.reserved[key]
			r.observe(
				key, r.edgeCapacity(key), total, true,
			)
			r.reserved[key] += amounts[i]
		}
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	successCount := failIndex
	if successCount < 0 {
		successCount = 0
	}
	if successCount > len(keys) {
		successCount = len(keys)
	}

	for i := 0; i < successCount; i++ {
		total := amounts[i] + r.reserved[keys[i]]
		r.observe(
			keys[i], r.edgeCapacity(keys[i]), total, true,
		)
	}

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.penalty[key] += 0.15
		}
		r.plan = nil
		return nil
	}

	failedKey := keys[failIndex]
	failedAmount := amounts[failIndex] + r.reserved[failedKey]
	r.penalty[failedKey] += 5

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		previous, ok := r.localFailures[failedKey]
		if !ok || failedAmount < previous {
			r.localFailures[failedKey] = failedAmount
		}
		r.observe(
			failedKey, r.edgeCapacity(failedKey),
			failedAmount, false,
		)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.badPolicy[failedKey] = true

	default:
		r.penalty[failedKey] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateMaxAttempts    = 72
	candidateMaxLabels      = 10
	candidateMaxPaths       = 56
	candidateBeamWidth      = 192
)

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi,
	checkMin bool) bool {

	if amt <= 0 || amt > e.capacity {
		return false
	}
	if checkMin && amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     uint8
}

var candidateSharedState = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateLiquidityFailure struct {
	amount lnwire.MilliSatoshi
	count  uint8
}

type candidateLimitMode uint8

const (
	candidateSafeLimit candidateLimitMode = iota
	candidateRetryLimit
	candidatePhysicalLimit
)

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	shared  map[candidateEdgeKey]candidateBelief
	current map[candidateEdgeKey]candidateBelief

	reserved        map[candidateEdgeKey]lnwire.MilliSatoshi
	edgePenalty     map[candidateEdgeKey]float64
	liquidityFailed map[candidateEdgeKey]candidateLiquidityFailure
	policyBad       map[candidateEdgeKey]bool

	plan     []*route.Route
	attempts uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edges:           make(map[candidateEdgeKey]*candidateEdge),
		localBalances:   localBalances,
		shared:          make(map[candidateEdgeKey]candidateBelief),
		current:         make(map[candidateEdgeKey]candidateBelief),
		reserved:        make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:     make(map[candidateEdgeKey]float64),
		liquidityFailed: make(map[candidateEdgeKey]candidateLiquidityFailure),
		policyBad:       make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateSharedState.Lock()
	for key, edge := range r.edges {
		belief, ok := candidateSharedState.beliefs[key]
		if !ok {
			continue
		}

		if belief.lowerOK > edge.capacity {
			belief.lowerOK = edge.capacity
		}
		if belief.upperBad > edge.capacity {
			belief.upperBad = edge.capacity
		}
		r.shared[key] = belief
	}
	candidateSharedState.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-ratio/0.025)
	highMode := 0.5 / (1 + math.Exp((ratio-0.93)/0.04))
	probability := lowMode + highMode

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.985 {
		return 0.985
	}
	return probability
}

func candidateEvidenceProbability(b candidateBelief,
	amt, capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.005
	}

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		position := float64(amt-b.lowerOK) /
			float64(b.upperBad-b.lowerOK)
		probability := 0.99 - 0.98*position

		if probability < 0.01 {
			return 0.01
		}
		if probability > 0.99 {
			return 0.99
		}
		return probability

	case b.upperBad > 0:
		ratio := float64(amt) / float64(b.upperBad)
		probability := 0.01 + 0.92*math.Exp(-ratio/0.20)
		if probability > 0.99 {
			return 0.99
		}
		return probability

	case b.lowerOK > 0:
		if capacity <= b.lowerOK {
			return 0.985
		}

		distance := float64(amt-b.lowerOK) / float64(capacity)
		probability := 0.62 + 0.36*math.Exp(-distance/0.20)
		if probability > 0.99 {
			return 0.99
		}
		return probability
	}

	return candidatePrior(amt, capacity)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	probability := candidatePrior(total, edge.capacity)

	if belief, ok := r.shared[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 4.0)
		if weight > 0.70 {
			weight = 0.70
		}
		probability = probability*(1-weight) + evidence*weight
	}

	if belief, ok := r.current[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 0.40)
		if weight > 0.98 {
			weight = 0.98
		}
		probability = probability*(1-weight) + evidence*weight
	}

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.995 {
		return 0.995
	}
	return probability
}

func candidateUpdateBelief(b candidateBelief,
	amt lnwire.MilliSatoshi, passed bool) candidateBelief {

	if amt <= 0 {
		return b
	}

	if passed {
		if b.upperBad > 0 && amt >= b.upperBad {
			b.upperBad = 0
			b.conf /= 2
		}
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
	} else {
		if b.lowerOK > 0 && amt <= b.lowerOK {
			b.lowerOK = 0
			b.conf /= 2
		}
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
	}

	if b.conf < 16 {
		b.conf++
	}
	return b
}

func (r *candidateRouter) learn(key candidateEdgeKey,
	currentAmt, sharedAmt lnwire.MilliSatoshi, passed bool) {

	r.current[key] = candidateUpdateBelief(
		r.current[key], currentAmt, passed,
	)

	if passed {
		r.edgePenalty[key] *= 0.35

		failed, ok := r.liquidityFailed[key]
		if ok {
			switch {
			case currentAmt >= failed.amount:
				delete(r.liquidityFailed, key)

			case failed.count > 1:
				failed.count--
				r.liquidityFailed[key] = failed
			}
		}
	}

	// A failed sibling in an atomic payment establishes a bound on the
	// aggregate held amount, not on the standalone shard amount.
	if !passed && currentAmt != sharedAmt {
		return
	}

	candidateSharedState.Lock()
	updated := candidateUpdateBelief(
		candidateSharedState.beliefs[key], sharedAmt, passed,
	)
	candidateSharedState.beliefs[key] = updated
	candidateSharedState.Unlock()

	r.shared[key] = updated
}

func (r *candidateRouter) markLiquidityFailure(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	failed, ok := r.liquidityFailed[key]
	if !ok || amount < failed.amount {
		failed.amount = amount
	}
	if failed.count < 8 {
		failed.count++
	}
	r.liquidityFailed[key] = failed
}

func (r *candidateRouter) failurePenalty(key candidateEdgeKey,
	total lnwire.MilliSatoshi) float64 {

	failed, ok := r.liquidityFailed[key]
	if !ok || failed.amount <= 0 || total <= 0 {
		return 0
	}

	ratio := float64(total) / float64(failed.amount)
	count := float64(failed.count)

	switch {
	case ratio >= 0.95:
		penalty := 360_000 * count
		if penalty > 1_500_000 {
			return 1_500_000
		}
		return penalty

	case ratio >= 0.70:
		return 145_000 * count

	case ratio >= 0.45:
		return 55_000 * count

	case ratio >= 0.25:
		return 15_000 * count

	default:
		return 0
	}
}

func (r *candidateRouter) addPenalty(key candidateEdgeKey, amount float64) {
	r.edgePenalty[key] += amount
	if r.edgePenalty[key] > 1_500_000 {
		r.edgePenalty[key] = 1_500_000
	}
}

func (r *candidateRouter) physicalTotal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	limit := edge.capacity
	if edge.key.from == r.source {
		local := r.localBalances[edge.key.chanID]
		if local < limit {
			limit = local
		}
	}
	return limit
}

func candidateRecommendedFromBelief(b candidateBelief,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	var result lnwire.MilliSatoshi

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		result = b.lowerOK + (b.upperBad-b.lowerOK)*28/100

	case b.upperBad > 0:
		result = b.upperBad * 30 / 100

	case b.lowerOK > 0:
		result = capacity * 88 / 100
		if b.lowerOK > result {
			result = b.lowerOK
		}

	default:
		result = capacity * 86 / 100
	}

	capLimit := capacity * 98 / 100
	if result > capLimit {
		result = capLimit
	}
	return result
}

func (r *candidateRouter) planningLimit(edge *candidateEdge,
	mode candidateLimitMode) lnwire.MilliSatoshi {

	physical := r.physicalTotal(edge)
	if physical <= 0 || mode == candidatePhysicalLimit ||
		edge.key.from == r.source {

		return physical
	}

	if belief, ok := r.current[edge.key]; ok {
		var limit lnwire.MilliSatoshi

		if mode == candidateSafeLimit {
			limit = candidateRecommendedFromBelief(
				belief, edge.capacity,
			)
		} else {
			switch {
			case belief.lowerOK > 0 &&
				belief.upperBad > belief.lowerOK:

				limit = belief.lowerOK +
					(belief.upperBad-belief.lowerOK)*62/100

			case belief.upperBad > 0:
				limit = belief.upperBad * 62 / 100

			case belief.lowerOK > 0:
				limit = edge.capacity * 92 / 100
				if belief.lowerOK > limit {
					limit = belief.lowerOK
				}

			default:
				limit = edge.capacity * 90 / 100
			}
		}

		if limit < physical {
			return limit
		}
		return physical
	}

	if mode == candidateSafeLimit {
		if belief, ok := r.shared[edge.key]; ok {
			limit := candidateRecommendedFromBelief(
				belief, edge.capacity,
			)
			if limit < physical {
				return limit
			}
			return physical
		}

		limit := edge.capacity * 86 / 100
		if limit < physical {
			return limit
		}
	}

	return physical
}

type candidatePathLabel struct {
	node     route.Vertex
	cost     float64
	arriving lnwire.MilliSatoshi
	path     []*candidateEdge
	alive    bool
}

type candidateQueue []*candidatePathLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	if q[i].cost == q[j].cost {
		return q[i].arriving < q[j].arriving
	}
	return q[i].cost < q[j].cost
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidatePathLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

func candidateDominates(a, b *candidatePathLabel) bool {
	return a.cost <= b.cost && a.arriving <= b.arriving
}

func candidatePathHasVertex(path []*candidateEdge,
	vertex route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == vertex || edge.key.to == vertex {
			return true
		}
	}
	return false
}

func candidateInsertLabel(
	labels map[route.Vertex][]*candidatePathLabel,
	pq *candidateQueue, label *candidatePathLabel) {

	existing := labels[label.node]
	for _, old := range existing {
		if old.alive && candidateDominates(old, label) {
			label.alive = false
			return
		}
	}

	kept := make([]*candidatePathLabel, 0, len(existing)+1)
	for _, old := range existing {
		if !old.alive {
			continue
		}
		if candidateDominates(label, old) {
			old.alive = false
			continue
		}
		kept = append(kept, old)
	}

	label.alive = true
	kept = append(kept, label)
	sort.Slice(kept, func(i, j int) bool {
		if kept[i].cost == kept[j].cost {
			return kept[i].arriving < kept[j].arriving
		}
		return kept[i].cost < kept[j].cost
	})

	if len(kept) > candidateMaxLabels {
		for _, dropped := range kept[candidateMaxLabels:] {
			dropped.alive = false
		}
		kept = kept[:candidateMaxLabels]
	}
	labels[label.node] = kept

	if label.alive {
		heap.Push(pq, label)
	}
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64,
	riskScale float64) ([]*candidateEdge, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	labels := make(map[route.Vertex][]*candidatePathLabel)
	pq := &candidateQueue{}
	initial := &candidatePathLabel{
		node:     r.spec.Target,
		arriving: amt,
		alive:    true,
	}
	labels[r.spec.Target] = []*candidatePathLabel{initial}
	heap.Push(pq, initial)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidatePathLabel)
		if !item.alive {
			continue
		}
		if item.node == r.source {
			return item.path, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				!edge.usable(item.arriving, true) {

				continue
			}
			if edge.key.from == item.node ||
				candidatePathHasVertex(item.path, edge.key.from) {

				continue
			}

			limit := r.physicalTotal(edge)
			total := item.arriving + r.reserved[edge.key]
			if limit <= 0 || total > limit {
				continue
			}

			probability := r.edgeProbability(edge, total)
			utilization := float64(total) / float64(limit)
			headroomCost := 115_000 * utilization *
				utilization * utilization

			edgeCost := -math.Log(probability)*riskScale +
				headroomCost + 72_000 +
				r.edgePenalty[edge.key] +
				r.failurePenalty(edge.key, total) +
				diversity[edge.key]

			sending := item.arriving
			if edge.key.from != r.source {
				fee := edge.fee(item.arriving)
				sending += fee
				edgeCost += float64(fee)
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			candidateInsertLabel(labels, pq, &candidatePathLabel{
				node:     edge.key.from,
				cost:     item.cost + edgeCost,
				arriving: sending,
				path:     path,
			})
		}
	}

	return nil, errors.New("no route found")
}

func candidateSamePath(a, b []*candidateEdge) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].key != b[i].key {
			return false
		}
	}
	return true
}

func candidatePathAmounts(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	amounts := make([]lnwire.MilliSatoshi, len(path))
	if len(path) == 0 {
		return amounts
	}

	amounts[len(path)-1] = finalAmt
	for i := len(path) - 2; i >= 0; i-- {
		amounts[i] = amounts[i+1] +
			path[i+1].fee(amounts[i+1])
	}
	return amounts
}

func (r *candidateRouter) pathWithin(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	mode candidateLimitMode, checkMin bool) bool {

	if finalAmt <= 0 || len(path) == 0 {
		return false
	}

	amounts := candidatePathAmounts(path, finalAmt)
	for i, edge := range path {
		if !edge.usable(amounts[i], checkMin) {
			return false
		}

		limit := r.planningLimit(edge, mode)
		total := amounts[i] + r.reserved[edge.key] +
			planned[edge.key]

		if limit <= 0 || total > limit {
			return false
		}
	}

	return true
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	want lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	mode candidateLimitMode) lnwire.MilliSatoshi {

	if want <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := want

	for low < high {
		mid := low + (high-low+1)/2
		if r.pathWithin(path, mid, planned, mode, false) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	if low == 0 ||
		!r.pathWithin(path, low, planned, mode, true) {

		return 0
	}
	return low
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	amounts := candidatePathAmounts(path, amt)
	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = candidateFinalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i+1 < len(path) {
			forwardAmt = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateAddPlanned(path []*candidateEdge,
	amt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		planned[edge.key] += amounts[i]
	}
}

func candidateClonePlanned(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

type candidateAllocation struct {
	routes    []*route.Route
	planned   map[candidateEdgeKey]lnwire.MilliSatoshi
	remaining lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
	hops      int
	rank      float64
}

func (r *candidateRouter) allocationQuality(
	state *candidateAllocation) float64 {

	quality := -float64(state.fee)/10_000_000 -
		0.035*float64(state.hops) -
		0.10*float64(len(state.routes))

	for key, amount := range state.planned {
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		total := amount + r.reserved[key]
		quality += math.Log(r.edgeProbability(edge, total))
		quality -= r.edgePenalty[key] / 850_000
		quality -= r.failurePenalty(key, total) / 700_000
	}

	return quality
}

func (r *candidateRouter) allocationRank(state *candidateAllocation,
	original lnwire.MilliSatoshi) float64 {

	coverage := float64(original-state.remaining) / float64(original)
	return 80*coverage + 0.25*r.allocationQuality(state)
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amount lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amount <= 0 {
		return amounts
	}
	for _, existing := range amounts {
		if existing == amount {
			return amounts
		}
	}
	return append(amounts, amount)
}

func candidateDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteEdge(rt *route.Route,
	index int) candidateEdgeKey {

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func (r *candidateRouter) routePlanRisk(rt *route.Route,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	result := 0.0
	for i := range rt.Hops {
		key := candidateRouteEdge(rt, i)
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		total := planned[key] + r.reserved[key]
		if total <= 0 {
			total = candidateRouteAmount(rt, i) + r.reserved[key]
		}

		result += math.Log(r.edgeProbability(edge, total))
		result -= r.edgePenalty[key] / 850_000
		result -= r.failurePenalty(key, total) / 700_000
	}

	return result
}

func (r *candidateRouter) orderPlan(routes []*route.Route,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi) {

	// Try the most fragile, largest commitments first. If they fail,
	// replanning happens before robust sibling routes occupy part slots.
	sort.SliceStable(routes, func(i, j int) bool {
		left := r.routePlanRisk(routes[i], planned)
		right := r.routePlanRisk(routes[j], planned)

		if left == right {
			return candidateDelivered(routes[i]) >
				candidateDelivered(routes[j])
		}
		return left < right
	})
}

func candidateTopCapacity(capacities []lnwire.MilliSatoshi,
	count int) lnwire.MilliSatoshi {

	if count <= 0 || len(capacities) == 0 {
		return 0
	}

	copyCaps := append([]lnwire.MilliSatoshi(nil), capacities...)
	sort.Slice(copyCaps, func(i, j int) bool {
		return copyCaps[i] > copyCaps[j]
	})

	if count > len(copyCaps) {
		count = len(copyCaps)
	}

	var total lnwire.MilliSatoshi
	for _, capacity := range copyCaps[:count] {
		total += capacity
	}
	return total
}

func (r *candidateRouter) allocatePlan(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int,
	mode candidateLimitMode) ([]*route.Route, bool) {

	initial := &candidateAllocation{
		planned:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		remaining: amt,
	}
	beam := []*candidateAllocation{initial}

	var best *candidateAllocation
	bestQuality := math.Inf(-1)

	for depth := 0; depth < parts && len(beam) > 0; depth++ {
		var next []*candidateAllocation

		for _, state := range beam {
			slots := parts - len(state.routes)
			if slots <= 0 || state.remaining <= 0 {
				continue
			}

			maxima := make([]lnwire.MilliSatoshi, len(paths))
			for i, path := range paths {
				maxima[i] = r.maxPathAmount(
					path, state.remaining,
					state.planned, mode,
				)
			}

			if candidateTopCapacity(maxima, slots) <
				state.remaining {

				continue
			}

			fair := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			futureCapacity := candidateTopCapacity(
				maxima, slots-1,
			)
			var needed lnwire.MilliSatoshi
			if futureCapacity < state.remaining {
				needed = state.remaining - futureCapacity
			}

			for pathIndex, path := range paths {
				maxAmount := maxima[pathIndex]
				if maxAmount <= 0 {
					continue
				}

				var choices []lnwire.MilliSatoshi
				if maxAmount >= state.remaining {
					choices = candidateAppendAmount(
						choices, state.remaining,
					)
				}

				choices = candidateAppendAmount(choices, maxAmount)

				fairAmount := fair
				if fairAmount > maxAmount {
					fairAmount = maxAmount
				}
				choices = candidateAppendAmount(choices, fairAmount)

				neededAmount := needed
				if neededAmount > maxAmount {
					neededAmount = maxAmount
				}
				choices = candidateAppendAmount(
					choices, neededAmount,
				)

				choices = candidateAppendAmount(
					choices, maxAmount*9/10,
				)
				choices = candidateAppendAmount(
					choices, maxAmount*2/3,
				)
				choices = candidateAppendAmount(
					choices, maxAmount/2,
				)
				choices = candidateAppendAmount(
					choices, maxAmount/3,
				)
				choices = candidateAppendAmount(
					choices, maxAmount/4,
				)

				for _, amount := range choices {
					if amount <= 0 ||
						amount > state.remaining ||
						!r.pathWithin(
							path, amount,
							state.planned, mode, true,
						) {

						continue
					}

					rt, err := r.buildRoute(path, amount)
					if err != nil {
						continue
					}

					planned := candidateClonePlanned(
						state.planned,
					)
					candidateAddPlanned(path, amount, planned)

					routes := append(
						[]*route.Route(nil),
						state.routes...,
					)
					routes = append(routes, rt)

					nextState := &candidateAllocation{
						routes:    routes,
						planned:   planned,
						remaining: state.remaining - amount,
						fee: state.fee +
							(rt.TotalAmount - amount),
						hops: state.hops + len(path),
					}

					if nextState.remaining == 0 {
						quality := r.allocationQuality(
							nextState,
						)
						if quality > bestQuality {
							best = nextState
							bestQuality = quality
						}
						continue
					}

					if len(nextState.routes) >= parts {
						continue
					}

					nextState.rank = r.allocationRank(
						nextState, amt,
					)
					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].rank > next[j].rank
		})
		if len(next) > candidateBeamWidth {
			next = next[:candidateBeamWidth]
		}
		beam = next
	}

	if best == nil {
		return nil, false
	}

	r.orderPlan(best.routes, best.planned)
	return best.routes, true
}

func candidateAppendProbe(probes []lnwire.MilliSatoshi,
	probe lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if probe <= 0 {
		return probes
	}
	for _, existing := range probes {
		if existing == probe {
			return probes
		}
	}
	return append(probes, probe)
}

func candidateCloneDiversity(
	source map[candidateEdgeKey]float64,
) map[candidateEdgeKey]float64 {

	result := make(map[candidateEdgeKey]float64, len(source))
	for key, value := range source {
		result[key] = value
	}
	return result
}

func (r *candidateRouter) discoverPaths(
	amt lnwire.MilliSatoshi, parts int) [][]*candidateEdge {

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var probes []lnwire.MilliSatoshi
	probes = candidateAppendProbe(probes, amt)
	probes = candidateAppendProbe(probes, base)
	probes = candidateAppendProbe(probes, base*3/2)
	probes = candidateAppendProbe(probes, base*3/4)
	probes = candidateAppendProbe(probes, base/2)
	probes = candidateAppendProbe(probes, base/3)
	probes = candidateAppendProbe(probes, base/4)
	probes = candidateAppendProbe(probes, base/8)
	probes = candidateAppendProbe(probes, base/16)
	probes = candidateAppendProbe(probes, base/64)

	riskScales := []float64{
		1_500_000,
		950_000,
		600_000,
		360_000,
		210_000,
	}

	globalDiversity := make(map[candidateEdgeKey]float64)
	var paths [][]*candidateEdge

	for _, probe := range probes {
		diversity := candidateCloneDiversity(globalDiversity)

		for round := 0; round < 9; round++ {
			path, err := r.findPath(
				probe, diversity,
				riskScales[round%len(riskScales)],
			)
			if err != nil {
				break
			}

			duplicate := false
			for _, existing := range paths {
				if candidateSamePath(existing, path) {
					duplicate = true
					break
				}
			}

			if !duplicate {
				paths = append(paths, path)
				for i, edge := range path {
					globalDiversity[edge.key] += 28_000
					if i == 0 || i == len(path)-1 {
						globalDiversity[edge.key] += 24_000
					}
				}

				if len(paths) >= candidateMaxPaths {
					return paths
				}
			}

			for i, edge := range path {
				diversity[edge.key] += 320_000
				if i == 0 || i == len(path)-1 {
					diversity[edge.key] += 260_000
				}
			}
		}
	}

	return paths
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts int) ([]*route.Route, error) {

	if parts < 1 {
		return nil, errors.New("maximum parts reached")
	}

	paths := r.discoverPaths(amt, parts)
	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}

	if plan, ok := r.allocatePlan(
		paths, amt, parts, candidateSafeLimit,
	); ok {
		return plan, nil
	}

	if plan, ok := r.allocatePlan(
		paths, amt, parts, candidateRetryLimit,
	); ok {
		return plan, nil
	}

	// Evidence is deliberately soft at the final stage. A stale or
	// amount-contingent failure must not turn into terminal abandonment
	// when gossip capacity still admits a complete route set.
	if plan, ok := r.allocatePlan(
		paths, amt, parts, candidatePhysicalLimit,
	); ok {
		return plan, nil
	}

	return nil, errors.New("no route set can carry payment")
}

func (r *candidateRouter) takeRoute(rt *route.Route) *route.Route {
	r.attempts++
	return rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}
	if r.attempts >= candidateMaxAttempts {
		return nil, errors.New("routing attempts exhausted")
	}

	if len(r.plan) > 0 {
		next := r.plan[0]
		if candidateDelivered(next) <= amt {
			r.plan = r.plan[1:]
			return r.takeRoute(next), nil
		}
		r.plan = nil
	}

	partsLeft := int(maxParts - inFlightHtlcs)
	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}
	if len(plan) == 0 {
		return nil, errors.New("empty route plan")
	}

	r.plan = plan[1:]
	return r.takeRoute(plan[0]), nil
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) learnRoutePassed(rt *route.Route,
	end int, reserve bool) {

	if end > len(rt.Hops) {
		end = len(rt.Hops)
	}

	for i := 0; i < end; i++ {
		key := candidateRouteEdge(rt, i)
		amt := candidateRouteAmount(rt, i)
		total := amt + r.reserved[key]
		r.learn(key, total, amt, true)
	}

	if reserve {
		for i := 0; i < end; i++ {
			key := candidateRouteEdge(rt, i)
			r.reserved[key] += candidateRouteAmount(rt, i)
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		r.learnRoutePassed(rt, len(rt.Hops), true)
		return nil
	}

	r.plan = nil

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)
	if failIndex > 0 {
		r.learnRoutePassed(rt, failIndex, false)
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			r.addPenalty(candidateRouteEdge(rt, i), 120_000)
		}
		return nil
	}

	key := candidateRouteEdge(rt, failIndex)
	amt := candidateRouteAmount(rt, failIndex)
	total := amt + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learn(key, total, amt, false)
		r.markLiquidityFailure(key, total)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[key] = true

	default:
		r.addPenalty(key, 700_000)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateMaxAttempts    = 64
	candidateBeamWidth      = 32
	candidateMaxLabels      = 4
	candidateMaxPaths       = 56
)

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi,
	checkMin bool) bool {

	if amt <= 0 || amt > e.capacity {
		return false
	}
	if checkMin && amt < e.minHTLC {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	conf     uint8
}

var candidateSharedState = struct {
	sync.Mutex
	beliefs map[candidateEdgeKey]candidateBelief
}{
	beliefs: make(map[candidateEdgeKey]candidateBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	shared  map[candidateEdgeKey]candidateBelief
	current map[candidateEdgeKey]candidateBelief

	reserved    map[candidateEdgeKey]lnwire.MilliSatoshi
	edgePenalty map[candidateEdgeKey]float64
	policyBad   map[candidateEdgeKey]bool

	pathPool  [][]*candidateEdge
	refreshes int
	plan      []*route.Route
	attempts  uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		shared:        make(map[candidateEdgeKey]candidateBelief),
		current:       make(map[candidateEdgeKey]candidateBelief),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		edgePenalty:   make(map[candidateEdgeKey]float64),
		policyBad:     make(map[candidateEdgeKey]bool),
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	candidateSharedState.Lock()
	for key := range r.edges {
		if belief, ok := candidateSharedState.beliefs[key]; ok {
			r.shared[key] = belief
		}
	}
	candidateSharedState.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.5 * math.Exp(-ratio/0.025)
	highMode := 0.5 / (1 + math.Exp((ratio-0.93)/0.04))
	probability := lowMode + highMode

	if probability < 0.005 {
		return 0.005
	}
	if probability > 0.985 {
		return 0.985
	}
	return probability
}

func candidateEvidenceProbability(b candidateBelief,
	amt, capacity lnwire.MilliSatoshi) float64 {

	if b.lowerOK > 0 && amt <= b.lowerOK {
		return 0.995
	}
	if b.upperBad > 0 && amt >= b.upperBad {
		return 0.005
	}

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		position := float64(amt-b.lowerOK) /
			float64(b.upperBad-b.lowerOK)
		probability := 0.99 - 0.98*position
		return math.Max(0.01, math.Min(0.99, probability))

	case b.upperBad > 0:
		ratio := float64(amt) / float64(b.upperBad)
		probability := 0.02 + 0.91*math.Exp(-ratio/0.13)
		return math.Min(0.99, probability)

	case b.lowerOK > 0:
		if capacity <= b.lowerOK {
			return 0.985
		}
		distance := float64(amt-b.lowerOK) / float64(capacity)
		probability := 0.60 + 0.38*math.Exp(-distance/0.22)
		return math.Min(0.99, probability)

	default:
		return candidatePrior(amt, capacity)
	}
}

func candidateUpdateBelief(b candidateBelief,
	amt lnwire.MilliSatoshi, passed bool) candidateBelief {

	if passed {
		if b.upperBad > 0 && amt >= b.upperBad {
			b.upperBad = 0
			b.conf /= 2
		}
		if amt > b.lowerOK {
			b.lowerOK = amt
		}
	} else {
		if b.lowerOK > 0 && amt <= b.lowerOK {
			b.lowerOK = 0
			b.conf /= 2
		}
		if b.upperBad == 0 || amt < b.upperBad {
			b.upperBad = amt
		}
	}

	if b.conf < 16 {
		b.conf++
	}
	return b
}

func (r *candidateRouter) learn(key candidateEdgeKey,
	currentAmt, sharedAmt lnwire.MilliSatoshi, passed bool) {

	r.current[key] = candidateUpdateBelief(
		r.current[key], currentAmt, passed,
	)
	r.shared[key] = candidateUpdateBelief(
		r.shared[key], sharedAmt, passed,
	)

	candidateSharedState.Lock()
	candidateSharedState.beliefs[key] = candidateUpdateBelief(
		candidateSharedState.beliefs[key], sharedAmt, passed,
	)
	candidateSharedState.Unlock()
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	probability := candidatePrior(total, edge.capacity)

	if belief, ok := r.shared[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		weight := float64(belief.conf) /
			(float64(belief.conf) + 2.5)
		if weight > 0.82 {
			weight = 0.82
		}
		probability = probability*(1-weight) + evidence*weight
	}

	if belief, ok := r.current[edge.key]; ok {
		evidence := candidateEvidenceProbability(
			belief, total, edge.capacity,
		)
		probability = 0.05*probability + 0.95*evidence
	}

	return math.Max(0.005, math.Min(0.995, probability))
}

func (r *candidateRouter) hardTotal(edge *candidateEdge) lnwire.MilliSatoshi {
	limit := edge.capacity
	if edge.key.from == r.source {
		if local := r.localBalances[edge.key.chanID]; local < limit {
			limit = local
		}
	}

	belief, ok := r.current[edge.key]
	if !ok || belief.upperBad == 0 {
		return limit
	}

	var retryLimit lnwire.MilliSatoshi
	if belief.lowerOK > 0 && belief.upperBad > belief.lowerOK {
		retryLimit = belief.lowerOK +
			(belief.upperBad-belief.lowerOK)*58/100
	} else {
		retryLimit = belief.upperBad * 58 / 100
	}

	if retryLimit < limit {
		limit = retryLimit
	}
	return limit
}

func candidateRecommendedFromBelief(b candidateBelief,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	var result lnwire.MilliSatoshi

	switch {
	case b.lowerOK > 0 && b.upperBad > b.lowerOK:
		result = b.lowerOK + (b.upperBad-b.lowerOK)*36/100

	case b.upperBad > 0:
		result = b.upperBad * 52 / 100

	case b.lowerOK > 0:
		result = capacity * 90 / 100
		if b.lowerOK > result {
			result = b.lowerOK
		}

	default:
		result = capacity * 82 / 100
	}

	capLimit := capacity * 98 / 100
	if result > capLimit {
		result = capLimit
	}
	return result
}

func (r *candidateRouter) recommendedTotal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	hard := r.hardTotal(edge)
	if edge.key.from == r.source {
		return hard
	}

	var recommended lnwire.MilliSatoshi
	if belief, ok := r.current[edge.key]; ok {
		recommended = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else if belief, ok := r.shared[edge.key]; ok {
		recommended = candidateRecommendedFromBelief(
			belief, edge.capacity,
		)
	} else {
		recommended = edge.capacity * 82 / 100
	}

	if recommended > hard {
		recommended = hard
	}
	return recommended
}

type candidateLabel struct {
	node     route.Vertex
	cost     float64
	arriving lnwire.MilliSatoshi
	path     []*candidateEdge
	active   bool
}

type candidateQueue []*candidateLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].cost < q[j].cost
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	item := old[len(old)-1]
	*q = old[:len(old)-1]
	return item
}

func candidatePathContains(path []*candidateEdge,
	node route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func candidateAdmitLabel(
	labels map[route.Vertex][]*candidateLabel,
	item *candidateLabel) bool {

	current := labels[item.node]
	for _, old := range current {
		if !old.active {
			continue
		}
		if old.cost <= item.cost &&
			old.arriving <= item.arriving {

			return false
		}
	}

	filtered := make([]*candidateLabel, 0, len(current)+1)
	for _, old := range current {
		if !old.active {
			continue
		}
		if item.cost <= old.cost &&
			item.arriving <= old.arriving {

			old.active = false
			continue
		}
		filtered = append(filtered, old)
	}

	item.active = true
	filtered = append(filtered, item)

	if len(filtered) > candidateMaxLabels {
		minCost, minAmount := 0, 0
		for i := 1; i < len(filtered); i++ {
			if filtered[i].cost < filtered[minCost].cost {
				minCost = i
			}
			if filtered[i].arriving <
				filtered[minAmount].arriving {

				minAmount = i
			}
		}

		worst := -1
		for i := range filtered {
			if i == minCost || i == minAmount {
				continue
			}
			if worst < 0 ||
				filtered[i].cost > filtered[worst].cost {

				worst = i
			}
		}
		if worst < 0 {
			worst = len(filtered) - 1
		}

		filtered[worst].active = false
		filtered = append(
			filtered[:worst], filtered[worst+1:]...,
		)
	}

	labels[item.node] = filtered
	return item.active
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64,
	riskScale float64) ([]*candidateEdge, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	labels := make(map[route.Vertex][]*candidateLabel)
	pq := &candidateQueue{}
	initial := &candidateLabel{
		node:     r.spec.Target,
		arriving: amt,
		active:   true,
	}
	labels[r.spec.Target] = []*candidateLabel{initial}
	heap.Push(pq, initial)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			return item.path, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBad[edge.key] ||
				candidatePathContains(item.path, edge.key.from) ||
				!edge.usable(item.arriving, true) {

				continue
			}

			limit := r.hardTotal(edge)
			total := item.arriving + r.reserved[edge.key]
			if limit <= 0 || total > limit {
				continue
			}

			probability := r.edgeProbability(edge, total)
			headroom := float64(total) / float64(limit)
			edgeCost := -math.Log(probability)*riskScale +
				110_000*headroom*headroom + 2_500 +
				r.edgePenalty[edge.key] + diversity[edge.key]

			sending := item.arriving
			if edge.key.from != r.source {
				fee := edge.fee(item.arriving)
				sending += fee
				edgeCost += float64(fee)
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			next := &candidateLabel{
				node:     edge.key.from,
				cost:     item.cost + edgeCost,
				arriving: sending,
				path:     path,
			}
			if !candidateAdmitLabel(labels, next) {
				continue
			}
			heap.Push(pq, next)
		}
	}

	return nil, errors.New("no route found")
}

func candidateSamePath(a, b []*candidateEdge) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].key != b[i].key {
			return false
		}
	}
	return true
}

func candidatePathAmounts(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	amounts := make([]lnwire.MilliSatoshi, len(path))
	if len(path) == 0 {
		return amounts
	}

	amounts[len(path)-1] = finalAmt
	for i := len(path) - 2; i >= 0; i-- {
		amounts[i] = amounts[i+1] +
			path[i+1].fee(amounts[i+1])
	}
	return amounts
}

func (r *candidateRouter) pathWithin(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe, checkMin bool) bool {

	if finalAmt <= 0 || len(path) == 0 {
		return false
	}

	amounts := candidatePathAmounts(path, finalAmt)
	for i, edge := range path {
		if r.policyBad[edge.key] ||
			!edge.usable(amounts[i], checkMin) {

			return false
		}

		limit := r.hardTotal(edge)
		if safe {
			limit = r.recommendedTotal(edge)
		}

		total := amounts[i] + r.reserved[edge.key] +
			planned[edge.key]
		if limit <= 0 || total > limit {
			return false
		}
	}

	return true
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	want lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	safe bool) lnwire.MilliSatoshi {

	if want <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := want
	for low < high {
		mid := low + (high-low+1)/2
		if r.pathWithin(path, mid, planned, safe, false) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	if low == 0 ||
		!r.pathWithin(path, low, planned, safe, true) {

		return 0
	}
	return low
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 || amt <= 0 {
		return nil, errors.New("empty route")
	}

	amounts := candidatePathAmounts(path, amt)
	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = candidateFinalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmt := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)
		if i+1 < len(path) {
			forwardAmt = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmt,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCloneAmounts(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func candidateCloneCounts(
	source map[candidateEdgeKey]uint8) map[candidateEdgeKey]uint8 {

	result := make(map[candidateEdgeKey]uint8, len(source))
	for key, count := range source {
		result[key] = count
	}
	return result
}

func candidateAddPlanned(path []*candidateEdge,
	amt lnwire.MilliSatoshi,
	planned map[candidateEdgeKey]lnwire.MilliSatoshi,
	used map[candidateEdgeKey]uint8) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		planned[edge.key] += amounts[i]
		used[edge.key]++
	}
}

func candidateAppendAmount(amounts []lnwire.MilliSatoshi,
	amount lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if amount <= 0 {
		return amounts
	}
	for _, existing := range amounts {
		if existing == amount {
			return amounts
		}
	}
	return append(amounts, amount)
}

type candidateLeg struct {
	path  []*candidateEdge
	amt   lnwire.MilliSatoshi
	route *route.Route
}

type candidateAllocation struct {
	legs      []candidateLeg
	planned   map[candidateEdgeKey]lnwire.MilliSatoshi
	used      map[candidateEdgeKey]uint8
	remaining lnwire.MilliSatoshi
	fee       lnwire.MilliSatoshi
	hops      int
	rank      float64
}

func (r *candidateRouter) allocationQuality(
	state *candidateAllocation) float64 {

	quality := -float64(state.fee)/20_000_000 -
		0.018*float64(state.hops) -
		0.08*float64(len(state.legs))

	for key, amount := range state.planned {
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		total := amount + r.reserved[key]
		quality += math.Log(r.edgeProbability(edge, total))
		quality -= r.edgePenalty[key] / 2_000_000

		if count := state.used[key]; count > 1 &&
			key.from != r.source {

			quality -= 0.20 * float64(count-1)
		}
	}

	return quality
}

func (r *candidateRouter) allocationRank(state *candidateAllocation,
	original lnwire.MilliSatoshi) float64 {

	coverage := float64(original-state.remaining) / float64(original)
	return 30*coverage + 0.55*r.allocationQuality(state)
}

func (r *candidateRouter) orderAllocation(
	state *candidateAllocation) []*route.Route {

	type scoredLeg struct {
		leg   candidateLeg
		score float64
	}

	scored := make([]scoredLeg, 0, len(state.legs))
	for _, leg := range state.legs {
		amounts := candidatePathAmounts(leg.path, leg.amt)
		score := 0.0
		for i, edge := range leg.path {
			total := state.planned[edge.key] +
				r.reserved[edge.key]
			score += math.Log(r.edgeProbability(edge, total))
			score -= r.edgePenalty[edge.key] / 2_000_000
			if amounts[i] > r.recommendedTotal(edge) {
				score -= 0.15
			}
		}
		scored = append(scored, scoredLeg{
			leg:   leg,
			score: score,
		})
	}

	sort.SliceStable(scored, func(i, j int) bool {
		difference := scored[i].score - scored[j].score
		if math.Abs(difference) > 0.05 {
			return scored[i].score < scored[j].score
		}
		return scored[i].leg.amt > scored[j].leg.amt
	})

	result := make([]*route.Route, len(scored))
	for i := range scored {
		result[i] = scored[i].leg.route
	}
	return result
}

func (r *candidateRouter) allocatePlan(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int,
	safe bool) ([]*route.Route, bool) {

	initial := &candidateAllocation{
		planned:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		used:      make(map[candidateEdgeKey]uint8),
		remaining: amt,
	}
	beam := []*candidateAllocation{initial}

	var best *candidateAllocation
	bestQuality := math.Inf(-1)

	for depth := 0; depth < parts && len(beam) != 0; depth++ {
		var next []*candidateAllocation

		for _, state := range beam {
			slots := parts - len(state.legs)
			if slots <= 0 {
				continue
			}

			fair := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			for _, path := range paths {
				maxAmount := r.maxPathAmount(
					path, state.remaining,
					state.planned, safe,
				)
				if maxAmount == 0 {
					continue
				}

				var choices []lnwire.MilliSatoshi
				choices = candidateAppendAmount(choices, maxAmount)

				fairAmount := fair
				if fairAmount > maxAmount {
					fairAmount = maxAmount
				}
				choices = candidateAppendAmount(choices, fairAmount)
				choices = candidateAppendAmount(
					choices, maxAmount*4/5,
				)
				choices = candidateAppendAmount(
					choices, maxAmount*3/5,
				)

				if maxAmount >= state.remaining {
					choices = candidateAppendAmount(
						choices, state.remaining,
					)
				}

				for _, amount := range choices {
					if amount > state.remaining ||
						!r.pathWithin(
							path, amount, state.planned,
							safe, true,
						) {

						continue
					}

					rt, err := r.buildRoute(path, amount)
					if err != nil {
						continue
					}

					planned := candidateCloneAmounts(
						state.planned,
					)
					used := candidateCloneCounts(state.used)
					candidateAddPlanned(
						path, amount, planned, used,
					)

					legs := append(
						[]candidateLeg(nil), state.legs...,
					)
					legs = append(legs, candidateLeg{
						path:  path,
						amt:   amount,
						route: rt,
					})

					nextState := &candidateAllocation{
						legs:      legs,
						planned:   planned,
						used:      used,
						remaining: state.remaining - amount,
						fee: state.fee +
							(rt.TotalAmount - amount),
						hops: state.hops + len(path),
					}

					if nextState.remaining == 0 {
						quality := r.allocationQuality(
							nextState,
						)
						if quality > bestQuality {
							best = nextState
							bestQuality = quality
						}
						continue
					}

					nextState.rank = r.allocationRank(
						nextState, amt,
					)
					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].rank > next[j].rank
		})
		if len(next) > candidateBeamWidth {
			next = next[:candidateBeamWidth]
		}
		beam = next
	}

	if best == nil {
		return nil, false
	}
	return r.orderAllocation(best), true
}

func candidateAppendProbe(probes []lnwire.MilliSatoshi,
	probe lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if probe <= 0 {
		return probes
	}
	for _, existing := range probes {
		if existing == probe {
			return probes
		}
	}
	return append(probes, probe)
}

func (r *candidateRouter) discoverPaths(
	amt lnwire.MilliSatoshi, parts int) [][]*candidateEdge {

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var probes []lnwire.MilliSatoshi
	probes = candidateAppendProbe(probes, amt)
	probes = candidateAppendProbe(probes, base*3/2)
	probes = candidateAppendProbe(probes, base)
	probes = candidateAppendProbe(probes, base*2/3)
	probes = candidateAppendProbe(probes, base/3)
	probes = candidateAppendProbe(probes, base/6)

	var paths [][]*candidateEdge

	for _, probe := range probes {
		if probe > amt {
			probe = amt
		}

		diversity := make(map[candidateEdgeKey]float64)
		for round := 0; round < 8; round++ {
			riskScale := 750_000.0
			switch round % 3 {
			case 0:
				riskScale = 1_250_000
			case 2:
				riskScale = 420_000
			}

			path, err := r.findPath(
				probe, diversity, riskScale,
			)
			if err != nil {
				break
			}

			duplicate := false
			for _, existing := range paths {
				if candidateSamePath(existing, path) {
					duplicate = true
					break
				}
			}
			if !duplicate {
				paths = append(paths, path)
			}

			for _, edge := range path {
				diversity[edge.key] += 1_900_000
			}
		}
	}

	return paths
}

func (r *candidateRouter) mergePaths(paths [][]*candidateEdge) {
	for _, path := range paths {
		duplicate := false
		for _, existing := range r.pathPool {
			if candidateSamePath(existing, path) {
				duplicate = true
				break
			}
		}
		if duplicate {
			continue
		}
		r.pathPool = append(r.pathPool, path)
		if len(r.pathPool) >= candidateMaxPaths {
			return
		}
	}
}

func (r *candidateRouter) fallbackScore(path []*candidateEdge,
	amt, paymentAmt lnwire.MilliSatoshi) float64 {

	amounts := candidatePathAmounts(path, amt)
	score := 6.0 * math.Log(
		float64(amt) / float64(paymentAmt),
	)

	for i, edge := range path {
		total := amounts[i] + r.reserved[edge.key]
		score += math.Log(r.edgeProbability(edge, total))
		score -= r.edgePenalty[edge.key] / 2_000_000
	}

	fee := amounts[0] - amt
	score -= float64(fee) / 20_000_000
	score -= 0.02 * float64(len(path))
	return score
}

func (r *candidateRouter) bestFallback(paths [][]*candidateEdge,
	amt lnwire.MilliSatoshi, parts int) *route.Route {

	planned := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	fair := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)
	minCommit := fair * 45 / 100

	bestScore := math.Inf(-1)
	var best *route.Route

	for _, path := range paths {
		hardMax := r.maxPathAmount(path, amt, planned, false)
		safeMax := r.maxPathAmount(path, amt, planned, true)

		var choices []lnwire.MilliSatoshi
		if parts == 1 {
			if hardMax >= amt {
				choices = candidateAppendAmount(choices, amt)
			}
		} else {
			choices = candidateAppendAmount(choices, safeMax)
			choices = candidateAppendAmount(choices, hardMax)

			fairAmount := fair
			if fairAmount > hardMax {
				fairAmount = hardMax
			}
			choices = candidateAppendAmount(choices, fairAmount)
			choices = candidateAppendAmount(
				choices, hardMax*3/4,
			)
		}

		for _, amount := range choices {
			if amount <= 0 || amount < minCommit ||
				!r.pathWithin(
					path, amount, planned, false, true,
				) {

				continue
			}

			score := r.fallbackScore(path, amount, amt)
			if score <= bestScore {
				continue
			}

			rt, err := r.buildRoute(path, amount)
			if err != nil {
				continue
			}
			best = rt
			bestScore = score
		}
	}

	return best
}

func (r *candidateRouter) completePlan(
	amt lnwire.MilliSatoshi, parts int) ([]*route.Route, bool) {

	if plan, ok := r.allocatePlan(
		r.pathPool, amt, parts, true,
	); ok {
		return plan, true
	}

	return r.allocatePlan(r.pathPool, amt, parts, false)
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts int) ([]*route.Route, error) {

	if parts < 1 {
		return nil, errors.New("maximum parts reached")
	}

	if len(r.pathPool) == 0 {
		r.mergePaths(r.discoverPaths(amt, parts))
		r.refreshes++
	}
	if len(r.pathPool) == 0 {
		return nil, errors.New("no route found")
	}

	if plan, ok := r.completePlan(amt, parts); ok {
		return plan, nil
	}

	if r.refreshes < 3 && len(r.pathPool) < candidateMaxPaths {
		r.mergePaths(r.discoverPaths(amt, parts))
		r.refreshes++
		if plan, ok := r.completePlan(amt, parts); ok {
			return plan, nil
		}
	}

	if fallback := r.bestFallback(
		r.pathPool, amt, parts,
	); fallback != nil {
		return []*route.Route{fallback}, nil
	}

	return nil, errors.New("no route set can carry payment")
}

func candidateDelivered(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) takeRoute(rt *route.Route) *route.Route {
	r.attempts++
	return rt
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid payment amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts reached")
	}
	if r.attempts >= candidateMaxAttempts {
		return nil, errors.New("routing attempts exhausted")
	}

	if len(r.plan) != 0 {
		next := r.plan[0]
		delivered := candidateDelivered(next)
		if delivered > 0 && delivered <= amt {
			r.plan = r.plan[1:]
			return r.takeRoute(next), nil
		}
		r.plan = nil
	}

	partsLeft := int(maxParts - inFlightHtlcs)
	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}
	if len(plan) == 0 {
		return nil, errors.New("empty route plan")
	}

	r.plan = plan[1:]
	return r.takeRoute(plan[0]), nil
}

func candidateRouteEdge(rt *route.Route,
	index int) candidateEdgeKey {

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func candidateRouteAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) learnRoutePassed(rt *route.Route,
	end int, reserve bool) {

	if end > len(rt.Hops) {
		end = len(rt.Hops)
	}

	for i := 0; i < end; i++ {
		key := candidateRouteEdge(rt, i)
		amt := candidateRouteAmount(rt, i)
		total := amt + r.reserved[key]
		r.learn(key, total, amt, true)
	}

	if reserve {
		for i := 0; i < end; i++ {
			key := candidateRouteEdge(rt, i)
			r.reserved[key] += candidateRouteAmount(rt, i)
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		r.learnRoutePassed(rt, len(rt.Hops), true)
		return nil
	}

	r.plan = nil

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)
	if failIndex > 0 {
		r.learnRoutePassed(rt, failIndex, false)
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key := candidateRouteEdge(rt, i)
			r.edgePenalty[key] += 500_000
		}
		return nil
	}

	key := candidateRouteEdge(rt, failIndex)
	amt := candidateRouteAmount(rt, failIndex)
	total := amt + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		// The failure tested aggregate liquidity, including held sibling
		// shards, so retain that aggregate threshold in both beliefs.
		r.learn(key, total, total, false)
		r.edgePenalty[key] += 400_000

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBad[key] = true

	default:
		r.edgePenalty[key] += 1_100_000
	}

	return nil
}
